INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION', 'CRE.G4.CREATI.SELF_AWARENESS', 'cre', 4, 'Know that each child is God''s special creation (Psalm 139:13-14, Genesis 1:27)', ARRAY['CRE.G4.CREATI.SELF_AWARENESS.b', 'CRE.G4.CREATI.SELF_AWARENESS.c']::text[], 'Says that God made each person, that each is unique and wonderfully made (Psalm 139:13-14), that people are made in God''s image (Genesis 1:27), and that being special does not mean being better than others. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what a verse says about how we are made","who made us","what makes each child special"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.FEELINGS', 'CRE.G4.CREATI.SELF_AWARENESS', 'cre', 4, 'Name good thoughts and feelings and cope with anger as Ephesians 4:26 and Philippians 4:4 teach', ARRAY['CRE.G4.CREATI.SELF_AWARENESS.a_', 'CRE.G4.CREATI.SELF_AWARENESS.b_', 'CRE.G4.CREATI.SELF_AWARENESS.c_']::text[], 'Names good thoughts (sharing, helping parents, being thankful), says why joy is good, and knows that Ephesians 4:26 says not to sin in anger or let the sun go down on it, and Philippians 4:4 says to rejoice in the Lord always. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a good thought or feeling","what a verse says about anger or joy","what to do with a feeling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.CHOICES', 'CRE.G4.CREATI.SELF_AWARENESS', 'cre', 4, 'Know the choices children make, their results, and how the word of God guides right choices', ARRAY['CRE.G4.CREATI.SELF_AWARENESS.a__', 'CRE.G4.CREATI.SELF_AWARENESS.b__', 'CRE.G4.CREATI.SELF_AWARENESS.c__']::text[], 'Names everyday choices, says that every choice has a result for the child and others, and chooses what pleases God (honest, kind, obedient) over what friends or feelings push for. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which is a choice","what a choice leads to","which choice pleases God"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY', 'CRE.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS', 'cre', 4, 'Name members of the nuclear and extended family and say why parents are honoured (Ephesians 6:1-3)', ARRAY['CRE.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.a', 'CRE.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.c']::text[], 'Tells the nuclear family (parents and children) from the extended family (grandparents, aunts, uncles, cousins), and knows that Ephesians 6:1-3 asks children to obey and honour their parents, and why. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who is in which family","what Ephesians 6:1-3 says","a way to honour parents"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION', 'CRE.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS', 'cre', 4, 'Know how a child protects himself or herself and whom to tell if touched wrongly', ARRAY['CRE.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.a_', 'CRE.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.b_', 'CRE.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.c_']::text[], 'Knows the body is private, that a child says NO, goes away and tells a trusted adult (a parent, a teacher, a church leader, the chief or the Childline Kenya helpline 116) if touched wrongly or asked to keep a secret, keeps telling until someone helps, and that it is never the child''s fault. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what to do in a situation","whom to tell","which gift or invitation to refuse"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES', 'CRE.G4.CREATI.ATTRIBUTES_OF_GOD', 'cre', 4, 'Know three attributes of God: sole creator, loving Father, holy (Genesis 1, 1 John 4:7-8, 1 Samuel 2:2)', ARRAY['CRE.G4.CREATI.ATTRIBUTES_OF_GOD.a', 'CRE.G4.CREATI.ATTRIBUTES_OF_GOD.b', 'CRE.G4.CREATI.ATTRIBUTES_OF_GOD.c']::text[], 'Says that God alone made everything (Genesis 1), that God is love and a loving Father (1 John 4:7-8), and that God is holy: there is none holy like the Lord (1 Samuel 2:2). Does not say that God shares making the world or loves only good children. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which attribute a verse shows","what an attribute means","which sentence about God is true"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS', 'CRE.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD', 'cre', 4, 'Tell the Old Testament from the New Testament and place well-known books', ARRAY['CRE.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.b']::text[], 'Places well-known books in the right Testament (Genesis, Exodus, Psalms, Isaiah in the Old; Matthew, Mark, Luke, John, Acts, Revelation in the New) and knows the first book of each. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which Testament a book is in","the first book","which books are the four Gospels"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS', 'CRE.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC', 'cre', 4, 'Know the story of Zacchaeus (Luke 19:2-10), how he changed and what repenting means', ARRAY['CRE.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.a', 'CRE.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.b', 'CRE.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.d']::text[], 'Says that Zacchaeus was a rich chief tax collector, short, who climbed a tree to see Jesus; that Jesus called him down and went to his house though the crowd grumbled; that he gave half his possessions to the poor and promised to repay four times anything taken wrongly; and that repenting means being sorry and turning from wrong. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Zacchaeus did to show he had changed","what repenting means"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM', 'CRE.G4.THE_HO.BALAAM_S_DONKEY', 'cre', 4, 'Know the story of Balaam and his donkey (Numbers 22) and why we obey God', ARRAY['CRE.G4.THE_HO.BALAAM_S_DONKEY.a', 'CRE.G4.THE_HO.BALAAM_S_DONKEY.b']::text[], 'Says that Balak king of Moab sent for Balaam, that God told him to say only what God told him, that the donkey saw the angel of the Lord with a drawn sword three times before Balaam did, that the Lord opened the donkey''s mouth and then Balaam''s eyes, and that the lesson is to obey God. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","who saw the angel first","the lesson of the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON', 'CRE.G4.THE_HO.SAMSON_KILLS_A_LION', 'cre', 4, 'Know how Samson killed a lion (Judges 14:5-9) and what it shows about God''s power', ARRAY['CRE.G4.THE_HO.SAMSON_KILLS_A_LION.a', 'CRE.G4.THE_HO.SAMSON_KILLS_A_LION.b', 'CRE.G4.THE_HO.SAMSON_KILLS_A_LION.c']::text[], 'Says that a young lion roared at Samson, that the Spirit of the Lord came powerfully on him, that he tore it apart with his bare hands, and that he did not tell his parents; and that the story shows God''s power at work in a person. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","where the strength came from","what the story shows about God"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM', 'CRE.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS', 'cre', 4, 'Know how Joseph interpreted Pharaoh''s dreams (Genesis 41:14-24, 28-30)', ARRAY['CRE.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.a', 'CRE.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.a_']::text[], 'Says that Pharaoh sent for Joseph from prison, that he dreamed of seven fat cows eaten by seven thin cows and of seven good ears of grain swallowed by seven thin ones, that Joseph said God would give the answer, and that the dreams meant seven years of plenty followed by seven years of famine. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the dreams","what the dreams meant","who gave the answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM', 'CRE.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS', 'cre', 4, 'Know that wisdom comes from God and what Proverbs 1:7 means by the fear of the Lord', ARRAY['CRE.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.b', 'CRE.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.b_', 'CRE.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.c', 'CRE.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.c_']::text[], 'Says that Joseph depended on God for the meaning of the dreams (Genesis 41:16), that Proverbs 1:7 says the fear of the Lord is the beginning of wisdom (knowledge), and that fearing the Lord means honouring and obeying him, not being afraid of him. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where Joseph''s wisdom came from","what the fear of the Lord means","a wise choice that depends on God"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM', 'CRE.G4.THE_HO.BIBLE_STRAND_QUESTION_S_', 'cre', 4, 'Know the call of Abraham (Genesis 12:1-5) and the change of his name (Genesis 17:1-5)', ARRAY['CRE.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.a', 'CRE.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.a_', 'CRE.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.b', 'CRE.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.b_', 'CRE.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.d', 'CRE.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.d_']::text[], 'Says that God told Abram to leave his country for a land God would show him, with the promise of a great nation and a blessing for all peoples (12:1-3), that Abram obeyed, taking Sarai and Lot, and that God changed his name to Abraham, a father of many nations (17:5). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the call","what God promised","the new name and its meaning","why Abraham obeyed"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION', 'CRE.G4.THE_LI.THE_ANNUNCIATION', 'cre', 4, 'Know the annunciation (Luke 1:26-37) and why the birth of Jesus is unique', ARRAY['CRE.G4.THE_LI.THE_ANNUNCIATION.a', 'CRE.G4.THE_LI.THE_ANNUNCIATION.b']::text[], 'Says that the angel Gabriel was sent to Mary at Nazareth, that Mary was engaged to Joseph, that she was told to name her son Jesus, that the Holy Spirit would come upon her, and that for God nothing is impossible (Luke 1:37). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what the angel said","what makes the birth unique"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH', 'CRE.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS', 'cre', 4, 'Know the birth of John the Baptist (Luke 1:5-13, 57, 76-79) and how he prepared the way', ARRAY['CRE.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.a', 'CRE.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.b']::text[], 'Says that Zechariah the priest and Elizabeth had no child and were old, that an angel appeared to Zechariah in the temple and told him to name the son John, that John was born, and that he would go before the Lord to prepare his way. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what the angel said","how John prepared the way"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'CRE.G4.THE_LI.HEALING_OF_BLIND_BARTIMA', 'cre', 4, 'Know the healing of blind Bartimaeus (Mark 10:46-52) and how he showed faith', ARRAY['CRE.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.a', 'CRE.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.a_', 'CRE.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.b', 'CRE.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.b_', 'CRE.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.c', 'CRE.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.c_']::text[], 'Says that Bartimaeus was a blind beggar by the road near Jericho, that he called out to Jesus, Son of David, and shouted louder when told to be quiet, that Jesus called him and asked what he wanted, that Jesus said his faith had healed him, and that he followed Jesus. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","how he showed faith","what Jesus said and did"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS', 'CRE.G4.THE_LI.HEALING_BY_THE_END_OF_TH', 'cre', 4, 'Know the healing of the ten lepers (Luke 17:11-19) and ways of showing gratitude to God', ARRAY['CRE.G4.THE_LI.HEALING_BY_THE_END_OF_TH.a', 'CRE.G4.THE_LI.HEALING_BY_THE_END_OF_TH.b', 'CRE.G4.THE_LI.HEALING_BY_THE_END_OF_TH.b_']::text[], 'Says that ten men with leprosy called to Jesus, that he told them to show themselves to the priests and they were cleansed on the way, that one, a Samaritan, came back praising God and thanked Jesus, and that Jesus asked where the other nine were; and gives ways of thanking God. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","who came back","a way of showing gratitude to God"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON', 'CRE.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S', 'cre', 4, 'Know how Jesus raised the widow''s son at Nain (Luke 7:11-16) and what it shows (John 11:25)', ARRAY['CRE.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.a', 'CRE.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.a_', 'CRE.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.b', 'CRE.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.b_', 'CRE.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.c', 'CRE.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.c_']::text[], 'Says that Jesus met a funeral at Nain for the only son of a widow, that his heart went out to her, that he touched the coffin and said "Young man, get up", that the young man sat up and spoke, and that it shows Jesus'' power over death and his compassion; and knows John 11:25. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what the miracle shows","how to show compassion"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.FORGIVENESS.FORGIVE', 'CRE.G4.THE_LI.FORGIVENESS', 'cre', 4, 'Know why we forgive and do not take revenge (Matthew 5:39)', ARRAY['CRE.G4.THE_LI.FORGIVENESS.a', 'CRE.G4.THE_LI.FORGIVENESS.b']::text[], 'Says that Matthew 5:39 teaches not to pay back evil with evil, gives reasons to forgive (peace, friendship, God forgives us), and knows that forgiving does not mean keeping quiet about being hurt: a child tells a trusted adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what Matthew 5:39 teaches","a reason to forgive","what to do when wronged"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING', 'CRE.G4.THE_LI.HELPING_THE_NEEDY', 'cre', 4, 'Know why and how we help people in need (Matthew 5:42)', ARRAY['CRE.G4.THE_LI.HELPING_THE_NEEDY.a']::text[], 'Says that Matthew 5:42 teaches giving to the one who asks, gives reasons for helping (love, God cares for the needy), and names ways a child helps at school, home and church (sharing a pencil or lunch, carrying a load, a visit). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what Matthew 5:42 teaches","a way to help","a good reason to help"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN', 'CRE.G4.THE_LI.PARABLE_OF_THE_LOST_COIN', 'cre', 4, 'Know the parable of the lost coin (Luke 15:8-10) and its lessons', ARRAY['CRE.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.a', 'CRE.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.b', 'CRE.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.c']::text[], 'Says that a woman with ten silver coins lost one, lit a lamp, swept the house and searched carefully until she found it, and called her friends to rejoice; and that the lesson is that God loves the sinner, searches for him and rejoices when he repents. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the parable","what the woman stands for","the lesson"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD', 'CRE.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S', 'cre', 4, 'Know the parable of the mustard seed (Luke 13:18-19) and how God''s kingdom grows', ARRAY['CRE.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.a', 'CRE.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.b', 'CRE.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.c']::text[], 'Says that a man planted a mustard seed in his garden, that it grew into a tree where birds perched, that God''s kingdom starts small and grows, and that a child helps it grow by praying, living well and telling others. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the parable","what the seed and the tree stand for","how a child helps the kingdom grow"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS', 'CRE.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH', 'cre', 4, 'Know Nicodemus'' meeting with Jesus (John 3:1-5) and John 3:16', ARRAY['CRE.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.a', 'CRE.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.b', 'CRE.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.d', 'CRE.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.c']::text[], 'Says that Nicodemus was a Pharisee and a member of the ruling council who came to Jesus at night, that Jesus told him one must be born again (of water and the Spirit), that Nicodemus did not first understand, and that John 3:16 says God so loved the world that he gave his Son so that whoever believes has eternal life. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Jesus told Nicodemus","what John 3:16 says"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS', 'CRE.G4.CHRIST.TRUST', 'cre', 4, 'Know how Joseph resisted temptation (Genesis 39:7-12)', ARRAY['CRE.G4.CHRIST.TRUST.a']::text[], 'Says that Potiphar''s wife tried to lead Joseph into wrong, that Joseph refused because it would be a sin against God, and that he ran out of the house leaving his cloak behind; and gives lessons (flee from temptation, fear God more than people). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","why Joseph refused","what to do when tempted"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CHRIST.TRUST.SAFE_PEOPLE', 'CRE.G4.CHRIST.TRUST', 'cre', 4, 'Know whom a child can trust for safety, and say NO to strangers and wrong requests', ARRAY['CRE.G4.CHRIST.TRUST.b', 'CRE.G4.CHRIST.TRUST.c']::text[], 'Names trusted people (parents, guardians, teachers, church leaders, the chief, police officers) and tells them from strangers, knows to refuse gifts, lifts and secrets from people who are not trusted, and to go away and tell. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["whom to trust","what to do when a stranger asks","whom to report to"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CHRIST.TRUST.TRUST_GOD', 'CRE.G4.CHRIST.TRUST', 'cre', 4, 'Know what Psalm 125:1 says about trusting in God', ARRAY['CRE.G4.CHRIST.TRUST.d']::text[], 'Says that Psalm 125:1 says those who trust in the Lord are like Mount Zion, which cannot be shaken but stands for ever; gives reasons to trust God (he is faithful, he cares, he is stronger than our fears) and knows that trusting God does not mean doing nothing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what Psalm 125:1 says","what trusting God means","a time to trust God"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH', 'CRE.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES', 'cre', 4, 'Know why we always tell the truth (Proverbs 12:19, Ephesians 4:25)', ARRAY['CRE.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.a', 'CRE.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.a_', 'CRE.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.b', 'CRE.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.b_']::text[], 'Says that Proverbs 12:19 teaches that truthful lips last and a lying tongue lasts only a moment, that Ephesians 4:25 says to put away falsehood and speak truthfully because we belong to one another, and gives reasons for telling the truth and ways of overcoming lies. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what a verse says about truth","why tell the truth","what to do after a lie"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE', 'CRE.G4.CHRIST.OBEDIENCE_OBEDIENCE', 'cre', 4, 'Know why we obey parents, teachers and school rules (Exodus 20:12) and what disobedience leads to', ARRAY['CRE.G4.CHRIST.OBEDIENCE_OBEDIENCE.a', 'CRE.G4.CHRIST.OBEDIENCE_OBEDIENCE.a_', 'CRE.G4.CHRIST.OBEDIENCE_OBEDIENCE.b', 'CRE.G4.CHRIST.OBEDIENCE_OBEDIENCE.b_', 'CRE.G4.CHRIST.OBEDIENCE_OBEDIENCE.d', 'CRE.G4.CHRIST.OBEDIENCE_OBEDIENCE.d_']::text[], 'Says that Exodus 20:12 tells children to honour father and mother and promises a long life in the land, gives reasons to obey parents, teachers and school rules (safety, peace, learning), and names results of disobedience (punishment, danger, lost trust). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what Exodus 20:12 says","why obey","a result of disobedience"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN', 'CRE.G4.CHRIST.LOVE_LOVE', 'cre', 4, 'Know how Jesus blessed the children (Matthew 19:13-15) and what it shows', ARRAY['CRE.G4.CHRIST.LOVE_LOVE.a', 'CRE.G4.CHRIST.LOVE_LOVE.a_']::text[], 'Says that people brought little children to Jesus to pray for them, that the disciples told them off, that Jesus said to let the children come to him and not hinder them, that the kingdom of heaven belongs to such as these, and that he placed his hands on them; and that God loves children. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Jesus said","what the story shows"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS', 'CRE.G4.CHRIST.RESPONSIBILITY_PERSONAL_', 'cre', 4, 'Know personal and school items and how to look after them', ARRAY['CRE.G4.CHRIST.RESPONSIBILITY_PERSONAL_.a', 'CRE.G4.CHRIST.RESPONSIBILITY_PERSONAL_.b']::text[], 'Names personal items (pullover, pen, exercise books, textbooks, school bag) and school property (desks, library books, latrines, tanks, trees), and says how each is cared for and why school property belongs to everyone. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which is a personal or school item","how to care for it","why care for school property"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.CHRIST.HOLINESS.HOLINESS', 'CRE.G4.CHRIST.HOLINESS', 'cre', 4, 'Know that the body is a temple of the Holy Spirit (1 Corinthians 6:19-20) and how to honour God with it', ARRAY['CRE.G4.CHRIST.HOLINESS.a', 'CRE.G4.CHRIST.HOLINESS.b', 'CRE.G4.CHRIST.HOLINESS.c']::text[], 'Says that 1 Corinthians 6:19-20 teaches that the body is a temple of the Holy Spirit and that we honour God with it, names ways of doing so (keeping clean, resting, avoiding drugs, using the body for good), and keeps away from places and company that lead to sin. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the verse says","a way of honouring God with the body","a situation to keep away from"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD', 'CRE.G4.THE_CH.HOUSE_OF_GOD', 'cre', 4, 'Know what Jesus did in the temple (Matthew 21:12-14) and why the church is a holy place', ARRAY['CRE.G4.THE_CH.HOUSE_OF_GOD.a']::text[], 'Says that Jesus drove out those buying and selling in the temple and overturned the tables of the money changers, said that God''s house is a house of prayer, and healed the blind and lame who came to him; and gives ways of respecting the church (1 Corinthians 14:26: everything done to build up the church). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Jesus said about the temple","a way of respecting the church"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES', 'CRE.G4.THE_CH.THE_EARLY_CHURCH', 'cre', 4, 'Name the twelve disciples (Matthew 10:1-4)', ARRAY['CRE.G4.THE_CH.THE_EARLY_CHURCH.a']::text[], 'Names disciples from Matthew 10:1-4 (Simon called Peter, Andrew, James and John sons of Zebedee, Philip, Bartholomew, Thomas, Matthew the tax collector, James son of Alphaeus, Thaddaeus, Simon the Zealot, Judas Iscariot), knows there were twelve, and does not count Paul among them. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which is a disciple","who the brothers were","how many disciples"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS', 'CRE.G4.THE_CH.THE_EARLY_CHURCH', 'cre', 4, 'Know how the early church began (Acts 2:38-41) and what Peter told the people', ARRAY['CRE.G4.THE_CH.THE_EARLY_CHURCH.b', 'CRE.G4.THE_CH.THE_EARLY_CHURCH.c']::text[], 'Says that Peter preached after the Holy Spirit came, that the people asked what to do, that he said to repent and be baptised for the forgiveness of sins, that about three thousand joined that day, and that repenting means turning away from sin. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Peter told the crowd","what repenting means"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN', 'CRE.G4.THE_CH.STANDING_FIRM_IN_FAITH', 'cre', 4, 'Know where believers were first called Christians (Acts 11:26) and how Stephen stood firm (Acts 7:54-60)', ARRAY['CRE.G4.THE_CH.STANDING_FIRM_IN_FAITH.a', 'CRE.G4.THE_CH.STANDING_FIRM_IN_FAITH.b', 'CRE.G4.THE_CH.STANDING_FIRM_IN_FAITH.c', 'CRE.G4.THE_CH.STANDING_FIRM_IN_FAITH.d']::text[], 'Says that believers were first called Christians at Antioch, that Stephen was stoned for his faith, looked up and saw Jesus, prayed for his attackers to be forgiven, and that the lessons are to stand firm, forgive enemies and not join groups that do not follow Jesus. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which city","recall a fact about Stephen","what lesson Stephen teaches","why avoid ungodly groups"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER', 'CRE.G4.THE_CH.THE_LORD_S_PRAYER', 'cre', 4, 'Know what the Lord''s Prayer (Matthew 6:9-13) asks for and why Christians pray every day', ARRAY['CRE.G4.THE_CH.THE_LORD_S_PRAYER.a', 'CRE.G4.THE_CH.THE_LORD_S_PRAYER.b']::text[], 'Says what the lines of the Lord''s Prayer ask for (God''s name honoured, his kingdom, daily bread, forgiveness as we forgive, keeping from temptation), that Jesus gave it as a pattern for prayer, and gives reasons to pray daily and for others. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what a line of the prayer asks for","why pray every day","whom to pray for"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'CRE.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT', 'cre', 4, 'Know the fruit of the Holy Spirit (Galatians 5:22-23) and how to show it', ARRAY['CRE.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.a', 'CRE.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.b']::text[], 'Lists the fruit of the Holy Spirit (love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, self-control), tells them from wrong behaviour, and shows which fruit fits a situation. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which is a fruit of the Spirit","which fruit fits a situation","what the verse says"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL', 'CRE.G4.THE_CH.SELF_CONTROL', 'cre', 4, 'Know what self-control is (Galatians 5:23-25) and how to avoid what defiles the body', ARRAY['CRE.G4.THE_CH.SELF_CONTROL.a', 'CRE.G4.THE_CH.SELF_CONTROL.b', 'CRE.G4.THE_CH.SELF_CONTROL.c']::text[], 'Says that self-control is a fruit of the Spirit and means choosing what is right instead of what the feeling says, that Galatians 5:25 says to keep in step with the Spirit, and avoids drugs, harmful videos and wrong behaviour that harm the body. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what self-control means","which choice shows self-control","what harms the body"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA', 'CRE.G4.MORALI.USE_OF_SOCIAL_MEDIA', 'cre', 4, 'Name digital devices and use social media safely and with integrity', ARRAY['CRE.G4.MORALI.USE_OF_SOCIAL_MEDIA.a', 'CRE.G4.MORALI.USE_OF_SOCIAL_MEDIA.b', 'CRE.G4.MORALI.USE_OF_SOCIAL_MEDIA.c']::text[], 'Names digital devices used at home and school (phone, tablet, computer), knows to keep passwords and home address private, never to chat with or meet strangers online, to tell a trusted adult about unsafe messages, not to pass on unkind messages, and to do right even when no one is watching. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which is a digital device","what to do online","what integrity means"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION', 'CRE.G3.CREATI.SELF_AWARENESS.a', 'outcome', 'essential', 'Proposed: this skill builds on it. To confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION', 'CRE.G3.CREATI.ADAM_AND_EVE.a', 'outcome', 'essential', 'The child already knows God made Adam and Eve; Psalm 139 says God made each person too. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
