INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER', 'CRE.G3.THE_CH.PRAYER.a', 'outcome', 'essential', 'Reciting the Lord''s Prayer from Matthew 6:9-13. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER', 'CRE.G2.THE_CH.PRAYER.b', 'outcome', 'essential', 'The friend at midnight, a story about keeping on praying. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'CRE.G3.THE_CH.THE_HOLY_SPIRIT.c', 'outcome', 'essential', 'Grade 3 named five fruit of the Spirit; Grade 4 learns all nine. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'CRE.G3.THE_CH.THE_HOLY_SPIRIT.b', 'outcome', 'essential', 'The work of the Holy Spirit in a Christian. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL', 'CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'skill', 'essential', 'Self-control is the last of the nine fruit. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL', 'CRE.G3.CREATI.SELF_AWARENESS.c', 'outcome', 'essential', 'Making right choices by God''s word. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA', 'CRE.G3.CHRIST.TRUST.a', 'outcome', 'essential', 'Proposed: this skill builds on it. To confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA', 'CRES.G4.CHRIST.TRUST.SAFE_PEOPLE', 'skill', 'essential', 'Knowing whom to trust and whom to tell comes before using social media. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA', 'CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH', 'skill', 'essential', 'Integrity online builds on telling the truth offline. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION.M_C4_UNIQ_BETTER', 'CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION', 'Thinks being special means being better than other people.', '{"question":"What does it mean that you are God''s special creation?","wrong_answer":"You are better than other children","correct_answer":"God made you with love and no one else is exactly like you"}'::jsonb, 'The word special is heard as a prize or a rank.', 'Offer "You are better than other children" beside "God made you with love and no one else is exactly like you" and ask the child to choose.', 'Say that every child is special in the same way, and ask each child to name one thing that makes a classmate special.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION.M_C4_UNIQ_ACCIDENT', 'CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION', 'Thinks a person is a chance event, without a plan or a maker.', '{"question":"According to Psalm 139:13-14, how did God make you?","wrong_answer":"By chance, with no plan","correct_answer":"He knit you together, fearfully and wonderfully made"}'::jsonb, 'Science lessons and talk about birth leave out God as the maker.', 'Offer "By chance, with no plan" beside "He knit you together, fearfully and wonderfully made" and ask the child to choose.', 'Read Psalm 139:13-14 slowly and ask who is doing the knitting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION.M_C4_UNIQ_FIRST_ONLY', 'CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION', 'Thinks God made only the first people, Adam and Eve, not each person today.', '{"question":"Who made you, according to the Bible?","wrong_answer":"God made only the first man and woman, and I came from my parents only","correct_answer":"God, who made every person in his image"}'::jsonb, 'The creation story is told as a story of long ago only.', 'Offer "God made only the first man and woman, and I came from my parents only" beside "God, who made every person in his image" and ask the child to choose.', 'Link Genesis 1:27 ("God created mankind in his own image") to Psalm 139:13 about each person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.FEELINGS.M_C4_FEEL_ANGER_SIN', 'CRES.G4.CREATI.SELF_AWARENESS.FEELINGS', 'Thinks that feeling angry is itself a sin.', '{"question":"What does Ephesians 4:26 say about anger?","wrong_answer":"Never feel angry at all","correct_answer":"Do not sin when you are angry"}'::jsonb, 'The child hears only the warning about anger.', 'Offer "Never feel angry at all" beside "Do not sin when you are angry" and ask the child to choose.', 'Read the verse: it says "in your anger do not sin". Ask what the angry child can do instead of hitting or shouting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.FEELINGS.M_C4_FEEL_KEEP_ANGER', 'CRES.G4.CREATI.SELF_AWARENESS.FEELINGS', 'Thinks you should keep anger inside until you can get even.', '{"question":"What should you do about anger, according to Ephesians 4:26?","wrong_answer":"Keep it and pay the person back later","correct_answer":"Settle it before the sun goes down"}'::jsonb, 'Revenge looks like justice to a hurt child.', 'Offer "Keep it and pay the person back later" beside "Settle it before the sun goes down" and ask the child to choose.', 'Role-play saying sorry or forgiving before bedtime.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.FEELINGS.M_C4_FEEL_JOY_GOOD_TIMES', 'CRES.G4.CREATI.SELF_AWARENESS.FEELINGS', 'Thinks we rejoice only when everything is going well.', '{"question":"What does Philippians 4:4 tell us to do?","wrong_answer":"Rejoice only when things go well","correct_answer":"Rejoice in the Lord always"}'::jsonb, 'Joy is mixed up with having what we want.', 'Offer "Rejoice only when things go well" beside "Rejoice in the Lord always" and ask the child to choose.', 'Ask whether we can be thankful to God even on a hard day, and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.CHOICES.M_C4_CHO_NO_RESULT', 'CRES.G4.CREATI.SELF_AWARENESS.CHOICES', 'Thinks a choice has no result if nobody sees it.', '{"question":"Kamau takes a pencil that is not his and nobody sees. What is true?","wrong_answer":"There is no result because nobody saw","correct_answer":"It still has results: he did wrong and he knows it"}'::jsonb, 'The child links wrong only to being caught.', 'Offer "There is no result because nobody saw" beside "It still has results: he did wrong and he knows it" and ask the child to choose.', 'List the results of one choice: for the child, for the owner, and before God.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.CHOICES.M_C4_CHO_FRIENDS', 'CRES.G4.CREATI.SELF_AWARENESS.CHOICES', 'Thinks the right choice is whatever friends are choosing.', '{"question":"Your friends tell you to skip class. How do you choose what to do?","wrong_answer":"Do what my friends do","correct_answer":"Choose what pleases God, even if my friends choose differently"}'::jsonb, 'Wanting to belong is stronger than wanting to be right.', 'Offer "Do what my friends do" beside "Choose what pleases God, even if my friends choose differently" and ask the child to choose.', 'Role-play a polite NO and walking to class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.CHOICES.M_C4_CHO_ONLY_BIG', 'CRES.G4.CREATI.SELF_AWARENESS.CHOICES', 'Thinks only big decisions are choices.', '{"question":"Which of these is a choice a child makes?","wrong_answer":"Only deciding which school to attend","correct_answer":"What to say, who to play with and whether to obey"}'::jsonb, 'The child links choosing with grown-up decisions.', 'Offer "Only deciding which school to attend" beside "What to say, who to play with and whether to obey" and ask the child to choose.', 'Make a list of the choices in one school morning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION.M_C4_UNIQ_LOOKS', 'CRES.G4.CREATI.SELF_AWARENESS.UNIQUE_CREATION', 'Thinks being made in God''s image means looking like God in face or skin colour.', '{"question":"What does it mean that people are made in the image of God (Genesis 1:27)?","wrong_answer":"People have the same face as God","correct_answer":"People are like God in being able to love, think and choose good"}'::jsonb, 'The word image is used at home for a photograph, so the child pictures a face.', 'Offer "People have the same face as God" beside "People are like God in being able to love, think and choose good" and ask the child to choose.', 'Show a photo and then a kind act: we show God''s image by how we love, not by our faces. Every skin colour carries God''s image.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.FEELINGS.M_C4_FEEL_SUN', 'CRES.G4.CREATI.SELF_AWARENESS.FEELINGS', 'Reads "do not let the sun go down" as a rule about the weather or bedtime, not about ending anger quickly.', '{"question":"What does \"do not let the sun go down while you are still angry\" (Ephesians 4:26) teach?","wrong_answer":"Go to bed before sunset","correct_answer":"Settle your anger the same day; do not keep it overnight"}'::jsonb, 'The child takes the picture word by word.', 'Offer "Go to bed before sunset" beside "Settle your anger the same day; do not keep it overnight" and ask the child to choose.', 'Ask: what happens at sunset? The day ends. So the verse says end your anger before the day ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.SELF_AWARENESS.CHOICES.M_C4_CHO_LUCK', 'CRES.G4.CREATI.SELF_AWARENESS.CHOICES', 'Thinks what happens after a choice is luck, not a result of the choice.', '{"question":"Achieng did not study and failed her test. Why did she fail?","wrong_answer":"Bad luck","correct_answer":"Her choice not to study had a result"}'::jsonb, 'The child has heard adults blame luck and does not link the choice with what follows.', 'Offer "Bad luck" beside "Her choice not to study had a result" and ask the child to choose.', 'Draw two arrows from one choice to its result. Ask the child to finish three such pairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY.M_C4_FAM_NUC_EXT', 'CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY', 'Mixes the nuclear and the extended family.', '{"question":"Who belongs to the extended family?","wrong_answer":"Only mother, father and children","correct_answer":"Grandparents, aunts, uncles and cousins"}'::jsonb, 'The two names sound alike.', 'Offer "Only mother, father and children" beside "Grandparents, aunts, uncles and cousins" and ask the child to choose.', 'Draw a small circle for the home and a bigger circle around it for relatives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY.M_C4_FAM_HOUSE_ONLY', 'CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY', 'Thinks family means only the people living in the same house.', '{"question":"Who counts as your family?","wrong_answer":"Only those who live in my house","correct_answer":"Those I live with and relatives who live elsewhere"}'::jsonb, 'Many children see relatives rarely, and forget they are family.', 'Offer "Only those who live in my house" beside "Those I live with and relatives who live elsewhere" and ask the child to choose.', 'Ask the child to name a relative who lives far away and how they keep in touch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY.M_C4_FAM_HONOUR_IF', 'CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY', 'Thinks honouring parents is only for when they give us things or agree with us.', '{"question":"When should a child honour his parents, according to Ephesians 6:1-3?","wrong_answer":"Only when they give me what I want","correct_answer":"Always, because it is right"}'::jsonb, 'Honour is mixed up with a bargain.', 'Offer "Only when they give me what I want" beside "Always, because it is right" and ask the child to choose.', 'Read Ephesians 6:1-3 and note the word "right" and the promise at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION.M_C4_PRO_SECRET', 'CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION', 'Thinks a child must keep a secret when an adult asks for it.', '{"question":"An adult touches you in a way that feels wrong and says \"keep it a secret\". What should you do?","wrong_answer":"Keep the secret so I do not get in trouble","correct_answer":"Say NO, go away and tell a trusted adult"}'::jsonb, 'The child fears trouble or is told to be quiet.', 'Offer "Keep the secret so I do not get in trouble" beside "Say NO, go away and tell a trusted adult" and ask the child to choose.', 'Say clearly: a secret about touching is never to be kept. Practise telling a teacher or parent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION.M_C4_PRO_STRANGER_ONLY', 'CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION', 'Thinks only strangers can hurt a child and that people we know are always safe.', '{"question":"Who might touch a child in a wrong way?","wrong_answer":"Only strangers","correct_answer":"Anyone, so a child must know what is not allowed and tell"}'::jsonb, 'Warnings about strangers hide that harm can come from known people.', 'Offer "Only strangers" beside "Anyone, so a child must know what is not allowed and tell" and ask the child to choose.', 'Teach the rule: private parts are private, whoever asks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION.M_C4_PRO_BLAME_SELF', 'CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION', 'Thinks it is the child''s fault if he or she is touched wrongly, so there is no need to tell.', '{"question":"A child was touched wrongly. Whose fault is it?","wrong_answer":"The child''s fault, so she should say nothing","correct_answer":"Never the child''s fault, and she should tell"}'::jsonb, 'Shame and fear stop a child from telling.', 'Offer "The child''s fault, so she should say nothing" beside "Never the child''s fault, and she should tell" and ask the child to choose.', 'Say it slowly: it is never your fault. Name the adults who will believe and help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY.M_C4_FAM_HONOUR_OBEY_WRONG', 'CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.FAMILY', 'Thinks honouring parents means doing anything an adult says, even something wrong or unsafe.', '{"question":"An adult relative tells you to steal from a shop. Does honouring your family mean you must do it?","wrong_answer":"Yes, I must obey every adult","correct_answer":"No: honour parents, but never do wrong; tell a trusted adult"}'::jsonb, 'Honour and obey are taught together, so the child thinks any instruction must be followed.', 'Offer "Yes, I must obey every adult" beside "No: honour parents, but never do wrong; tell a trusted adult" and ask the child to choose.', 'Ephesians 6:1 says obey parents "in the Lord": in what is right. Practise saying no politely to a wrong request.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION.M_C4_PRO_ONCE_ONLY', 'CRES.G4.CREATI.MY_FAMILY_FAMILY_MEMBERS.PROTECTION', 'Thinks a child need not tell if the wrong touch happened only once or the person said sorry.', '{"question":"A person touched you wrongly once and said sorry. Should you still tell a trusted adult?","wrong_answer":"No, it was only once","correct_answer":"Yes, always tell a trusted adult"}'::jsonb, 'The child wants to keep the peace and thinks one time is too small to report.', 'Offer "No, it was only once" beside "Yes, always tell a trusted adult" and ask the child to choose.', 'Repeat the rule with no exceptions: say no, go away, tell. Name three trusted adults the child could tell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES.M_C4_ATT_SHARED', 'CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES', 'Thinks God made the world together with others or that others made parts of it.', '{"question":"Who made everything, according to Genesis 1?","wrong_answer":"God and other gods together","correct_answer":"God alone"}'::jsonb, 'Stories from other places mention many makers.', 'Offer "God and other gods together" beside "God alone" and ask the child to choose.', 'Read Genesis 1:1 and count how many makers are named.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES.M_C4_ATT_LOVE_EARNED', 'CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES', 'Thinks God loves only children who are good.', '{"question":"What does 1 John 4:7-8 say about God?","wrong_answer":"God loves only the children who are always good","correct_answer":"God is love"}'::jsonb, 'A child learns that bad behaviour is punished and thinks love is the same.', 'Offer "God loves only the children who are always good" beside "God is love" and ask the child to choose.', 'Read "God is love" and ask whether love is a reward.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES.M_C4_ATT_HOLY_BIG', 'CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES', 'Thinks holy means big, old or far away.', '{"question":"What does holy mean when we say God is holy?","wrong_answer":"Very big and old","correct_answer":"Perfect and set apart, without sin"}'::jsonb, 'The word is not used in daily speech.', 'Offer "Very big and old" beside "Perfect and set apart, without sin" and ask the child to choose.', 'Link it to 1 Samuel 2:2: there is no one holy like the Lord.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES.M_C4_ATT_ANGRY_JUDGE', 'CRES.G4.CREATI.ATTRIBUTES_OF_GOD.ATTRIBUTES', 'Thinks God is mainly angry and waiting to punish, so a loving Father cannot also be holy.', '{"question":"Can God be both holy and a loving Father?","wrong_answer":"No, a holy God is only angry","correct_answer":"Yes: God is holy and God is love"}'::jsonb, 'The child pictures a stern ruler and cannot hold two attributes together.', 'Offer "No, a holy God is only angry" beside "Yes: God is holy and God is love" and ask the child to choose.', 'Put the two words side by side, holy and love, and read 1 Samuel 2:2 and 1 John 4:8. God is both at once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS.M_C4_BK_NT_IN_OT', 'CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS', 'Puts a New Testament book in the Old Testament.', '{"question":"Which book is in the Old Testament?","wrong_answer":"Matthew","correct_answer":"Genesis"}'::jsonb, 'The child knows the names but not the two parts.', 'Offer "Matthew" beside "Genesis" and ask the child to choose.', 'Draw the Bible in two halves and sort book names on cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS.M_C4_BK_OT_IN_NT', 'CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS', 'Puts an Old Testament book in the New Testament.', '{"question":"Which book is in the New Testament?","wrong_answer":"Psalms","correct_answer":"Acts"}'::jsonb, 'The child links Psalms or Isaiah with church songs and readings.', 'Offer "Psalms" beside "Acts" and ask the child to choose.', 'Sort the cards again and say which half each belongs to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS.M_C4_BK_FIRST', 'CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS', 'Says Matthew is the first book of the whole Bible, mixing the first book of the New Testament with the first of the Old.', '{"question":"Which is the first book of the Bible?","wrong_answer":"Matthew","correct_answer":"Genesis"}'::jsonb, 'Matthew is the first book children meet in the New Testament.', 'Offer "Matthew" beside "Genesis" and ask the child to choose.', 'Open a Bible together at the first page.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS.M_C4_BK_COUNT', 'CRES.G4.THE_HO.THE_INSPIRED_WORD_OF_GOD.BIBLE_BOOKS', 'Swaps the number of books in the two Testaments.', '{"question":"How many books are in the Old Testament in the Protestant Bible?","wrong_answer":"27","correct_answer":"39"}'::jsonb, 'Both numbers were learnt in Grades 2 and 3 and the child mixes which is which.', 'Offer "27" beside "39" and ask the child to choose.', 'Remember: the Old Testament is the older, longer part: 39. The New Testament: 27. Check on the contents page.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS.M_C4_ZAC_NUMBERS', 'CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS', 'Mixes the amounts Zacchaeus promised.', '{"question":"What did Zacchaeus promise to give to the poor?","wrong_answer":"All that he owned","correct_answer":"Half of what he owned"}'::jsonb, 'The child remembers that he gave a lot, not how much.', 'Offer "All that he owned" beside "Half of what he owned" and ask the child to choose.', 'Read Luke 19:8 and underline half and four times.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS.M_C4_ZAC_CROWD_GLAD', 'CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS', 'Thinks the crowd was pleased when Jesus went to Zacchaeus'' house.', '{"question":"What did the people say when Jesus went to Zacchaeus'' house?","wrong_answer":"They were glad and thanked Jesus","correct_answer":"They grumbled that he went to a sinner"}'::jsonb, 'The child imagines a happy ending for everyone.', 'Offer "They were glad and thanked Jesus" beside "They grumbled that he went to a sinner" and ask the child to choose.', 'Read Luke 19:7 and ask why they grumbled.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS.M_C4_ZAC_SORRY_ONLY', 'CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS', 'Thinks repenting means only saying sorry, with no change.', '{"question":"What does it mean to repent?","wrong_answer":"To say sorry in words and go on as before","correct_answer":"To be sorry for wrong and turn away from it"}'::jsonb, 'Saying sorry is quick, changing is hard.', 'Offer "To say sorry in words and go on as before" beside "To be sorry for wrong and turn away from it" and ask the child to choose.', 'Ask what Zacchaeus did that showed he meant it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS.M_C4_ZAC_TREE_WHY', 'CRES.G4.THE_HO.ZACCHAEUS_THE_TAX_COLLEC.ZACCHAEUS', 'Thinks Zacchaeus climbed the tree to hide from Jesus.', '{"question":"Why did Zacchaeus climb the sycamore-fig tree (Luke 19:3-4)?","wrong_answer":"To hide from Jesus","correct_answer":"He was short and wanted to see Jesus over the crowd"}'::jsonb, 'The child knows Zacchaeus was a sinner and expects him to hide.', 'Offer "To hide from Jesus" beside "He was short and wanted to see Jesus over the crowd" and ask the child to choose.', 'Read Luke 19:3-4 aloud and act it: a short child behind a crowd cannot see. Zacchaeus wanted to see Jesus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM.M_C4_BAL_SAW_FIRST', 'CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM', 'Thinks Balaam saw the angel first.', '{"question":"Who saw the angel of the Lord first?","wrong_answer":"Balaam","correct_answer":"The donkey"}'::jsonb, 'The child expects the prophet to see more than an animal.', 'Offer "Balaam" beside "The donkey" and ask the child to choose.', 'Read Numbers 22:23 and 22:31 side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM.M_C4_BAL_CURSE_OK', 'CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM', 'Thinks God allowed Balaam to curse the Israelites.', '{"question":"What was Balaam told to do about the Israelites?","wrong_answer":"Curse them, for money","correct_answer":"Say only what God told him, and not curse them"}'::jsonb, 'The child follows the king''s offer and forgets God''s word.', 'Offer "Curse them, for money" beside "Say only what God told him, and not curse them" and ask the child to choose.', 'Read Numbers 22:12 and 22:20 aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM.M_C4_BAL_STUBBORN', 'CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM', 'Thinks the donkey was stubborn and deserved to be beaten.', '{"question":"Why did the donkey turn aside and lie down?","wrong_answer":"Because she was stubborn","correct_answer":"Because she saw the angel and was protecting Balaam"}'::jsonb, 'Balaam''s own words in the story make the donkey sound stubborn.', 'Offer "Because she was stubborn" beside "Because she saw the angel and was protecting Balaam" and ask the child to choose.', 'Read Numbers 22:33 where the angel explains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM.M_C4_BAL_DONKEY_SELF', 'CRES.G4.THE_HO.BALAAM_S_DONKEY.BALAAM', 'Thinks the donkey could always talk, like an animal in a fable.', '{"question":"How was the donkey able to speak to Balaam (Numbers 22:28)?","wrong_answer":"Donkeys could talk in those days","correct_answer":"The Lord opened the donkey''s mouth"}'::jsonb, 'The child knows talking animals from fables and folk tales.', 'Offer "Donkeys could talk in those days" beside "The Lord opened the donkey''s mouth" and ask the child to choose.', 'Read Numbers 22:28: "the Lord opened the donkey''s mouth". It was a miracle, not a fable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON.M_C4_SAM_WEAPON', 'CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON', 'Thinks Samson killed the lion with a weapon.', '{"question":"How did Samson kill the lion in Judges 14?","wrong_answer":"With a sword","correct_answer":"With his bare hands"}'::jsonb, 'Heroes in stories use weapons.', 'Offer "With a sword" beside "With his bare hands" and ask the child to choose.', 'Read Judges 14:6 and look for any weapon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON.M_C4_SAM_OWN_STRENGTH', 'CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON', 'Thinks Samson was strong by himself, not by God''s power.', '{"question":"Where did Samson''s strength come from in this story?","wrong_answer":"From his own muscles alone","correct_answer":"From the Spirit of the Lord who came upon him"}'::jsonb, 'Stories about strong men credit the man.', 'Offer "From his own muscles alone" beside "From the Spirit of the Lord who came upon him" and ask the child to choose.', 'Read the words "the Spirit of the Lord came powerfully upon him".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON.M_C4_SAM_TOLD', 'CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON', 'Thinks Samson told his parents about the lion.', '{"question":"What did Samson tell his parents about the lion?","wrong_answer":"He told them everything at once","correct_answer":"He told them nothing about it"}'::jsonb, 'The child expects a boy to boast of such a deed.', 'Offer "He told them everything at once" beside "He told them nothing about it" and ask the child to choose.', 'Read Judges 14:6 to the end of the verse.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON.M_C4_SAM_HONEY_TOLD', 'CRES.G4.THE_HO.SAMSON_KILLS_A_LION.SAMSON', 'Thinks Samson told his parents the honey came from the lion.', '{"question":"When Samson gave his parents honey (Judges 14:9), what did he tell them?","wrong_answer":"That it came from the dead lion","correct_answer":"He did not tell them where it came from"}'::jsonb, 'The child expects a son to tell parents everything and fills the gap.', 'Offer "That it came from the dead lion" beside "He did not tell them where it came from" and ask the child to choose.', 'Read Judges 14:9 slowly; stop at "he did not tell them". Ask what the verse says, not what he should have done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM.M_C4_JD_OWN_POWER', 'CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM', 'Thinks Joseph worked out the dream by his own cleverness.', '{"question":"Who gave the meaning of Pharaoh''s dreams, according to Joseph?","wrong_answer":"Joseph, because he was clever","correct_answer":"God"}'::jsonb, 'Children admire clever people in stories.', 'Offer "Joseph, because he was clever" beside "God" and ask the child to choose.', 'Read Genesis 41:16: "I cannot do it, but God will give Pharaoh the answer".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM.M_C4_JD_NUMBERS', 'CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM', 'Mixes the numbers in the dreams.', '{"question":"How many years of plenty did the seven fat cows stand for?","wrong_answer":"Three years","correct_answer":"Seven years"}'::jsonb, 'The child remembers the cows but not what they stood for.', 'Offer "Three years" beside "Seven years" and ask the child to choose.', 'Draw the seven fat cows and write a year under each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM.M_C4_JD_REVERSED', 'CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM', 'Reverses what the fat and thin cows meant.', '{"question":"What did the seven thin cows eating the fat cows mean?","wrong_answer":"Seven years of plenty","correct_answer":"Seven years of famine that would swallow up the plenty"}'::jsonb, 'Fat sounds bad and thin sounds weak.', 'Offer "Seven years of plenty" beside "Seven years of famine that would swallow up the plenty" and ask the child to choose.', 'Draw it: fat cows are plenty, thin cows are famine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM.M_C4_JW_TERROR', 'CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM', 'Thinks the fear of the Lord means being terrified of God.', '{"question":"What does \"the fear of the Lord\" mean in Proverbs 1:7?","wrong_answer":"To be scared of God and hide from him","correct_answer":"To honour God and obey him"}'::jsonb, 'The word fear means fright in daily speech.', 'Offer "To be scared of God and hide from him" beside "To honour God and obey him" and ask the child to choose.', 'Compare with respecting a good teacher or a loving parent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM.M_C4_JW_SCHOOL_ONLY', 'CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM', 'Thinks wisdom comes only from school or from age.', '{"question":"Where does true wisdom begin, according to Proverbs 1:7?","wrong_answer":"With being old and having many degrees","correct_answer":"With honouring the Lord"}'::jsonb, 'The child links wisdom with grown-ups and school.', 'Offer "With being old and having many degrees" beside "With honouring the Lord" and ask the child to choose.', 'Remind the child that Joseph was a young man in prison.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM.M_C4_JW_SELF_GLORY', 'CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM', 'Thinks that a wise person should take the praise for himself.', '{"question":"Joseph was praised by Pharaoh. What did Joseph first say?","wrong_answer":"That he alone was wise","correct_answer":"That God gives the answer"}'::jsonb, 'Praise is pleasant and children think it belongs to the one praised.', 'Offer "That he alone was wise" beside "That God gives the answer" and ask the child to choose.', 'Read Genesis 41:16 and ask who got the credit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM.M_C4_JD_GRAIN_COWS', 'CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_DREAM', 'Thinks Pharaoh had only one dream, about cows, and forgets the heads of grain.', '{"question":"What were Pharaoh''s two dreams about (Genesis 41:17-24)?","wrong_answer":"One dream about cows only","correct_answer":"Seven fat and seven thin cows, then seven full and seven thin heads of grain"}'::jsonb, 'The cows are the vivid part and the second dream is lost in retelling.', 'Offer "One dream about cows only" beside "Seven fat and seven thin cows, then seven full and seven thin heads of grain" and ask the child to choose.', 'Draw both dreams side by side and ask the child to say what they share: seven good, seven poor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM.M_C4_JW_CLEVER_EQUALS', 'CRES.G4.THE_HO.JOSEPH_JOSEPH_INTERPRETS.JOSEPH_WISDOM', 'Thinks a wise person is simply one who knows many facts or gets top marks.', '{"question":"Who is wise, according to Proverbs 1:7?","wrong_answer":"The one with the most marks","correct_answer":"The one who honours the Lord and does what is right"}'::jsonb, 'School praises marks, so the child equates wisdom with marks.', 'Offer "The one with the most marks" beside "The one who honours the Lord and does what is right" and ask the child to choose.', 'Compare two people: one with top marks who cheats, one who honours God and is fair. Which is wise?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM.M_C4_ABR_KNEW_PLACE', 'CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM', 'Thinks God told Abram exactly where he was going.', '{"question":"What did God say about the land Abram would go to?","wrong_answer":"He named the exact place","correct_answer":"It was a land God would show him"}'::jsonb, 'The child thinks of a map and a clear destination.', 'Offer "He named the exact place" beside "It was a land God would show him" and ask the child to choose.', 'Read Genesis 12:1 and find the words "that I will show you".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM.M_C4_ABR_ALONE', 'CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM', 'Thinks Abram left alone.', '{"question":"Who went with Abram to the new land?","wrong_answer":"Nobody, he went alone","correct_answer":"Sarai his wife and Lot his nephew, with their people"}'::jsonb, 'The child pictures one man walking out.', 'Offer "Nobody, he went alone" beside "Sarai his wife and Lot his nephew, with their people" and ask the child to choose.', 'Read Genesis 12:4-5 and list the people named.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM.M_C4_ABR_NAME', 'CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM', 'Mixes up the old and new names or what Abraham means.', '{"question":"What did God change Abram''s name to, and what does it mean?","wrong_answer":"Abraham means a great sea","correct_answer":"Abraham means father of many nations"}'::jsonb, 'Names and their meanings are easy to mix.', 'Offer "Abraham means a great sea" beside "Abraham means father of many nations" and ask the child to choose.', 'Read Genesis 17:5 aloud: "I have made you a father of many nations".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM.M_C4_ABR_AGE', 'CRES.G4.THE_HO.BIBLE_STRAND_QUESTION_S_.ABRAHAM', 'Mixes up Abram''s age when God called him with his age when his name was changed.', '{"question":"How old was Abram when he left Haran (Genesis 12:4)?","wrong_answer":"99 years old","correct_answer":"75 years old"}'::jsonb, 'The two numbers come from two chapters and the child joins them.', 'Offer "99 years old" beside "75 years old" and ask the child to choose.', 'Put two cards on a time line: Genesis 12, age 75, the call; Genesis 17, age 99, the new name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION.M_C4_ANN_ZECHARIAH', 'CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION', 'Mixes Gabriel''s visit to Mary with his visit to Zechariah.', '{"question":"To whom did the angel Gabriel bring the news of Jesus'' birth?","wrong_answer":"Zechariah in the temple","correct_answer":"Mary at Nazareth"}'::jsonb, 'Luke 1 tells two angel visits in a row.', 'Offer "Zechariah in the temple" beside "Mary at Nazareth" and ask the child to choose.', 'Make two columns: Zechariah and Mary, and place the facts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION.M_C4_ANN_PLACE', 'CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION', 'Places the annunciation in Bethlehem, where Jesus was born, instead of Nazareth, where Mary lived.', '{"question":"Where was Mary when the angel came to her?","wrong_answer":"Bethlehem","correct_answer":"Nazareth in Galilee"}'::jsonb, 'Jesus is born in Bethlehem, so the child puts everything there.', 'Offer "Bethlehem" beside "Nazareth in Galilee" and ask the child to choose.', 'Read Luke 1:26 and then say where Jesus was born later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION.M_C4_ANN_NAME', 'CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION', 'Gives the name John, the name Zechariah was told, for the child Mary was told to name Jesus.', '{"question":"What name did the angel tell Mary to give her son?","wrong_answer":"John","correct_answer":"Jesus"}'::jsonb, 'The names of the two babies get mixed.', 'Offer "John" beside "Jesus" and ask the child to choose.', 'Read Luke 1:31 and Luke 1:13 and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION.M_C4_ANN_AFRAID_DOUBT', 'CRES.G4.THE_LI.THE_ANNUNCIATION.ANNUNCIATION', 'Thinks Mary refused the angel''s message because she was afraid.', '{"question":"What did Mary finally say to the angel (Luke 1:38)?","wrong_answer":"\"I cannot do this\"","correct_answer":"\"I am the Lord''s servant. May it be to me as you have said.\""}'::jsonb, 'Mary asked "How will this be?", which the child hears as a refusal.', 'Offer ""I cannot do this"" beside ""I am the Lord''s servant. May it be to me as you have said."" and ask the child to choose.', 'Read Luke 1:34 and 1:38 together. Asking a question is not saying no.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH.M_C4_JB_MOTHER', 'CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH', 'Mixes up the parents of John and of Jesus.', '{"question":"Who were John the Baptist''s parents?","wrong_answer":"Mary and Joseph","correct_answer":"Zechariah and Elizabeth"}'::jsonb, 'Both births are in Luke 1.', 'Offer "Mary and Joseph" beside "Zechariah and Elizabeth" and ask the child to choose.', 'Draw two family trees for the two babies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH.M_C4_JB_MESSIAH', 'CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH', 'Thinks John the Baptist was the Messiah.', '{"question":"What was John''s work, according to Luke 1:76?","wrong_answer":"To be the Messiah","correct_answer":"To go before the Lord and prepare his way"}'::jsonb, 'John''s fame makes the child think he was the Lord.', 'Offer "To be the Messiah" beside "To go before the Lord and prepare his way" and ask the child to choose.', 'Read Luke 1:76: "you will go on before the Lord to prepare the way for him".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH.M_C4_JB_YOUNG_PARENTS', 'CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH', 'Thinks Zechariah and Elizabeth were young.', '{"question":"What was true about Zechariah and Elizabeth in Luke 1:7?","wrong_answer":"They were young and had many children","correct_answer":"They had no child and were well along in years"}'::jsonb, 'The child expects a birth to be to a young couple.', 'Offer "They were young and had many children" beside "They had no child and were well along in years" and ask the child to choose.', 'Read Luke 1:7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH.M_C4_JB_MUTE', 'CRES.G4.THE_LI.BIRTH_OF_JOHN_THE_BAPTIS.JOHN_BIRTH', 'Thinks Zechariah spoke the name John out loud when the baby was named.', '{"question":"How did Zechariah give the name John (Luke 1:63)?","wrong_answer":"He shouted it in the temple","correct_answer":"He wrote it on a tablet, because he could not speak"}'::jsonb, 'The child forgets that Zechariah was unable to speak until the naming.', 'Offer "He shouted it in the temple" beside "He wrote it on a tablet, because he could not speak" and ask the child to choose.', 'Read Luke 1:20 and 1:63-64: he could not speak, so he wrote "His name is John", and then his tongue was set free.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS.M_C4_BART_QUIET', 'CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'Thinks Bartimaeus kept quiet when the crowd told him to.', '{"question":"What did Bartimaeus do when many people told him to be quiet?","wrong_answer":"He kept quiet","correct_answer":"He shouted even louder"}'::jsonb, 'The child expects politeness to win.', 'Offer "He kept quiet" beside "He shouted even louder" and ask the child to choose.', 'Read Mark 10:48 and find the word "louder".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS.M_C4_BART_TOUCH', 'CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'Thinks Jesus touched his eyes or used a method.', '{"question":"How did Jesus heal Bartimaeus, according to Mark 10:52?","wrong_answer":"He touched his eyes","correct_answer":"He said \"your faith has healed you\""}'::jsonb, 'Other healings in the Gospels use a touch.', 'Offer "He touched his eyes" beside "He said "your faith has healed you"" and ask the child to choose.', 'Read Mark 10:52 and look for any touching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS.M_C4_BART_WENT_HOME', 'CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'Thinks Bartimaeus went home after he could see.', '{"question":"What did Bartimaeus do after he could see?","wrong_answer":"Went home to his family","correct_answer":"Followed Jesus along the road"}'::jsonb, 'Healed people in other stories go home.', 'Offer "Went home to his family" beside "Followed Jesus along the road" and ask the child to choose.', 'Read the last words of Mark 10:52.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS.M_C4_BART_TOWN', 'CRES.G4.THE_LI.HEALING_OF_BLIND_BARTIMA.BARTIMAEUS', 'Places the healing of Bartimaeus in Nazareth or Jerusalem instead of near Jericho.', '{"question":"Where was Jesus when he healed Bartimaeus (Mark 10:46)?","wrong_answer":"In Nazareth","correct_answer":"Leaving Jericho"}'::jsonb, 'Nazareth and Jerusalem are the towns the child knows best.', 'Offer "In Nazareth" beside "Leaving Jericho" and ask the child to choose.', 'Read Mark 10:46 and point at Jericho on a map; say "blind beggar by the Jericho road".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS.M_C4_LEP_COUNT', 'CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS', 'Thinks all ten lepers came back to thank Jesus.', '{"question":"How many of the ten lepers came back to thank Jesus?","wrong_answer":"All ten","correct_answer":"One"}'::jsonb, 'The child expects healed people to be thankful.', 'Offer "All ten" beside "One" and ask the child to choose.', 'Read Luke 17:15 and 17:17: "Where are the other nine?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS.M_C4_LEP_WHO', 'CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS', 'Thinks the one who returned was a priest or a Jew.', '{"question":"Who was the man who came back to thank Jesus?","wrong_answer":"A priest","correct_answer":"A Samaritan"}'::jsonb, 'The child does not know why the detail is stressed.', 'Offer "A priest" beside "A Samaritan" and ask the child to choose.', 'Read Luke 17:16: "and he was a Samaritan".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS.M_C4_LEP_THANKS_NEED', 'CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS', 'Thinks we should talk to God only when we need something.', '{"question":"When should we thank God?","wrong_answer":"Only when we need help","correct_answer":"Every day, for what he gives us"}'::jsonb, 'Prayer is learned as asking.', 'Offer "Only when we need help" beside "Every day, for what he gives us" and ask the child to choose.', 'List five things to thank God for today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS.M_C4_LEP_HEALED_THERE', 'CRES.G4.THE_LI.HEALING_BY_THE_END_OF_TH.LEPERS', 'Thinks the lepers were healed on the spot when Jesus touched them.', '{"question":"When were the ten lepers healed (Luke 17:14)?","wrong_answer":"As soon as Jesus touched them","correct_answer":"As they went on their way to the priests"}'::jsonb, 'Many healing stories have a touch, so the child adds one here.', 'Offer "As soon as Jesus touched them" beside "As they went on their way to the priests" and ask the child to choose.', 'Read Luke 17:14: "as they went, they were cleansed". Act walking away and being healed on the road.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON.M_C4_WID_JAIRUS', 'CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON', 'Mixes the widow''s son with the daughter of Jairus.', '{"question":"Who did Jesus raise at Nain?","wrong_answer":"The daughter of Jairus","correct_answer":"The only son of a widow"}'::jsonb, 'Both are raisings from the dead in the Gospels, and the child learned Jairus'' daughter in Grade 3.', 'Offer "The daughter of Jairus" beside "The only son of a widow" and ask the child to choose.', 'Make two columns: Nain and Jairus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON.M_C4_WID_ASKED', 'CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON', 'Thinks the crowd begged Jesus to raise the son.', '{"question":"Why did Jesus raise the widow''s son?","wrong_answer":"The crowd begged him to","correct_answer":"His heart went out to the widow and he had compassion"}'::jsonb, 'In other miracles people ask for help.', 'Offer "The crowd begged him to" beside "His heart went out to the widow and he had compassion" and ask the child to choose.', 'Read Luke 7:13.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON.M_C4_WID_HUSBAND', 'CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON', 'Mixes up who had died.', '{"question":"Who had died in the story of the widow at Nain?","wrong_answer":"Her husband","correct_answer":"Her only son"}'::jsonb, 'The word widow suggests a husband who died.', 'Offer "Her husband" beside "Her only son" and ask the child to choose.', 'Read Luke 7:12: "the only son of his mother, and she was a widow".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON.M_C4_WID_PRAYED_LONG', 'CRES.G4.THE_LI.JESUS_RAISES_A_WIDOW_S_S.WIDOW_SON', 'Thinks Jesus prayed a long prayer at the funeral before the young man rose.', '{"question":"What did Jesus say to the dead young man (Luke 7:14)?","wrong_answer":"A long prayer for the family","correct_answer":"\"Young man, I say to you, get up!\""}'::jsonb, 'The child links a funeral with long prayers and fills that in.', 'Offer "A long prayer for the family" beside ""Young man, I say to you, get up!"" and ask the child to choose.', 'Read Luke 7:14 aloud. Jesus touched the coffin and spoke a few words with power.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.FORGIVENESS.FORGIVE.M_C4_FOR_REVENGE', 'CRES.G4.THE_LI.FORGIVENESS.FORGIVE', 'Thinks paying back evil with evil is fair.', '{"question":"Someone hits you. According to Matthew 5:39, what should you do?","wrong_answer":"Hit back so they learn","correct_answer":"Not pay back evil with evil"}'::jsonb, 'Revenge feels like fairness to a hurt child.', 'Offer "Hit back so they learn" beside "Not pay back evil with evil" and ask the child to choose.', 'Role-play walking away and telling the teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.FORGIVENESS.FORGIVE.M_C4_FOR_WEAK', 'CRES.G4.THE_LI.FORGIVENESS.FORGIVE', 'Thinks forgiving is weakness or means letting people hurt you again and again.', '{"question":"Is forgiving a sign of weakness?","wrong_answer":"Yes, strong children hit back","correct_answer":"No, it takes strength, and you may still tell an adult"}'::jsonb, 'Strength is thought to be shown by fighting.', 'Offer "Yes, strong children hit back" beside "No, it takes strength, and you may still tell an adult" and ask the child to choose.', 'Say that forgiving is a choice and that telling a teacher keeps you safe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.FORGIVENESS.FORGIVE.M_C4_FOR_FORGET', 'CRES.G4.THE_LI.FORGIVENESS.FORGIVE', 'Thinks forgiving means pretending nothing happened.', '{"question":"What does it mean to forgive someone?","wrong_answer":"To pretend it never happened","correct_answer":"To let go of the wish to pay back"}'::jsonb, 'Forgiving and forgetting are said together.', 'Offer "To pretend it never happened" beside "To let go of the wish to pay back" and ask the child to choose.', 'Ask what changes in us when we stop planning revenge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.FORGIVENESS.FORGIVE.M_C4_FOR_CHEEK_LITERAL', 'CRES.G4.THE_LI.FORGIVENESS.FORGIVE', 'Thinks Matthew 5:39 means a child must stand still and let a bully keep hitting.', '{"question":"What does \"turn the other cheek\" (Matthew 5:39) ask a child to do when hit by a bully?","wrong_answer":"Stand still and let him keep hitting","correct_answer":"Not hit back, walk away and tell a trusted adult"}'::jsonb, 'The picture is taken word for word, without the meaning of not taking revenge.', 'Offer "Stand still and let him keep hitting" beside "Not hit back, walk away and tell a trusted adult" and ask the child to choose.', 'Explain: the verse is about not paying back. A child still goes to a safe place and tells a teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING.M_C4_HELP_RICH', 'CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING', 'Thinks only people with a lot can help.', '{"question":"Who can help someone in need?","wrong_answer":"Only rich people","correct_answer":"Anyone, even with a little"}'::jsonb, 'Help is linked with money.', 'Offer "Only rich people" beside "Anyone, even with a little" and ask the child to choose.', 'List what a child with no money can give: time, a pencil, a kind word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING.M_C4_HELP_MONEY_ONLY', 'CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING', 'Thinks helping means giving money only.', '{"question":"Which of these is a way of helping a person in need?","wrong_answer":"Only giving money","correct_answer":"Sharing food, carrying a load or visiting"}'::jsonb, 'Adults'' giving is seen as money.', 'Offer "Only giving money" beside "Sharing food, carrying a load or visiting" and ask the child to choose.', 'Make a list of ways to help at home, school and church.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING.M_C4_HELP_PRAISE', 'CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING', 'Thinks we help so that others will praise us.', '{"question":"Why should a Christian help the needy?","wrong_answer":"So that people will praise me","correct_answer":"Because of love for God and for others"}'::jsonb, 'Prizes and praise at school teach children to want a reward.', 'Offer "So that people will praise me" beside "Because of love for God and for others" and ask the child to choose.', 'Ask whether Jesus helped for praise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING.M_C4_HELP_LATER', 'CRES.G4.THE_LI.HELPING_THE_NEEDY.HELPING', 'Thinks a child can wait to help until it is convenient, though Matthew 5:42 says give to the one who asks.', '{"question":"A classmate has no pencil for the test and asks you. What does Matthew 5:42 teach?","wrong_answer":"Help after the test if I remember","correct_answer":"Give or lend now, to the one who asks"}'::jsonb, 'The child puts his own comfort first and does not see delay as refusing.', 'Offer "Help after the test if I remember" beside "Give or lend now, to the one who asks" and ask the child to choose.', 'Act it: the test starts now. Help that comes later is no help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN.M_C4_COIN_NINE', 'CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN', 'Mixes the number of coins.', '{"question":"How many silver coins did the woman have before she lost one?","wrong_answer":"Nine","correct_answer":"Ten"}'::jsonb, 'The nine that were left are remembered.', 'Offer "Nine" beside "Ten" and ask the child to choose.', 'Read Luke 15:8: "ten silver coins".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN.M_C4_COIN_GAVE_UP', 'CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN', 'Thinks the woman soon gave up.', '{"question":"What did the woman do about the lost coin?","wrong_answer":"She gave up because she had nine more","correct_answer":"She lit a lamp and searched until she found it"}'::jsonb, 'Children give up when something is small.', 'Offer "She gave up because she had nine more" beside "She lit a lamp and searched until she found it" and ask the child to choose.', 'Read Luke 15:8 and note "until she finds it".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN.M_C4_COIN_MONEY_LESSON', 'CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN', 'Reads the parable as a lesson about money.', '{"question":"What does the parable of the lost coin teach?","wrong_answer":"Count your money carefully","correct_answer":"God searches for the lost and rejoices when a sinner repents"}'::jsonb, 'The story is about a coin.', 'Offer "Count your money carefully" beside "God searches for the lost and rejoices when a sinner repents" and ask the child to choose.', 'Read Luke 15:10 for Jesus'' own meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN.M_C4_COIN_ALONE', 'CRES.G4.THE_LI.PARABLE_OF_THE_LOST_COIN.COIN', 'Thinks the woman kept the good news to herself.', '{"question":"What did the woman do when she found the coin (Luke 15:9)?","wrong_answer":"Hid it and told no one","correct_answer":"Called her friends and neighbours to rejoice with her"}'::jsonb, 'The child thinks of money as private.', 'Offer "Hid it and told no one" beside "Called her friends and neighbours to rejoice with her" and ask the child to choose.', 'Read Luke 15:9-10 and link it: the party on earth is like the joy in heaven over one sinner who repents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD.M_C4_MUS_BIG_START', 'CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD', 'Thinks God''s kingdom started big and mighty.', '{"question":"How does God''s kingdom begin, in the parable of the mustard seed?","wrong_answer":"With a very big and powerful start","correct_answer":"Very small, like a seed, and then it grows"}'::jsonb, 'People expect God''s kingdom to be grand at once.', 'Offer "With a very big and powerful start" beside "Very small, like a seed, and then it grows" and ask the child to choose.', 'Plant a seed in the school compound and watch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD.M_C4_MUS_BIRDS', 'CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD', 'Misreads what the birds did.', '{"question":"What happened to the birds in the parable?","wrong_answer":"They ate the seed","correct_answer":"They perched in the branches of the tree"}'::jsonb, 'The child brings an idea of birds eating seed from farm life.', 'Offer "They ate the seed" beside "They perched in the branches of the tree" and ask the child to choose.', 'Read Luke 13:19.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD.M_C4_MUS_ADULTS_ONLY', 'CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD', 'Thinks only pastors or adults can help the kingdom of God grow.', '{"question":"Who can help God''s kingdom grow?","wrong_answer":"Only pastors and adults","correct_answer":"Every Christian, including children"}'::jsonb, 'Church work is seen as grown-up work.', 'Offer "Only pastors and adults" beside "Every Christian, including children" and ask the child to choose.', 'List what a child can do: pray, be kind, invite a friend to church.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD.M_C4_MUS_REAL_FARMING', 'CRES.G4.THE_LI.PARABLE_OF_THE_MUSTARD_S.MUSTARD', 'Thinks the parable is a lesson about growing mustard on a farm.', '{"question":"What is the parable of the mustard seed about (Luke 13:18-19)?","wrong_answer":"How to plant mustard","correct_answer":"How God''s kingdom grows from a small beginning"}'::jsonb, 'Parables use farm pictures, and the child stays with the picture.', 'Offer "How to plant mustard" beside "How God''s kingdom grows from a small beginning" and ask the child to choose.', 'Ask Jesus'' own question first: "What is the kingdom of God like?" The seed is a picture of the kingdom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS.M_C4_NIC_DAY', 'CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS', 'Thinks Nicodemus came to Jesus in the daytime.', '{"question":"When did Nicodemus come to Jesus?","wrong_answer":"At noon, in front of everyone","correct_answer":"At night"}'::jsonb, 'The child does not remember the detail.', 'Offer "At noon, in front of everyone" beside "At night" and ask the child to choose.', 'Read John 3:2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS.M_C4_NIC_LITERAL', 'CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS', 'Thinks Jesus meant being born a second time from a mother.', '{"question":"What did Jesus mean by \"born again\"?","wrong_answer":"To be born a second time from one''s mother","correct_answer":"A new life from God by water and the Spirit"}'::jsonb, 'Nicodemus himself asked this in John 3:4.', 'Offer "To be born a second time from one''s mother" beside "A new life from God by water and the Spirit" and ask the child to choose.', 'Read John 3:4-5 together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS.M_C4_NIC_FEW', 'CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS', 'Thinks God loves only some people.', '{"question":"Whom does God love, according to John 3:16?","wrong_answer":"Only the Jews","correct_answer":"The whole world"}'::jsonb, 'The child thinks the Bible stories are about one nation.', 'Offer "Only the Jews" beside "The whole world" and ask the child to choose.', 'Read John 3:16 and underline "world".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS.M_C4_NIC_BAPTISM_MAGIC', 'CRES.G4.THE_LI.NICODEMUS_ENCOUNTER_WITH.NICODEMUS', 'Thinks baptism is only a water ceremony and changes nothing in how a person lives.', '{"question":"Why is baptism important to Christians today?","wrong_answer":"It is only a nice ceremony with water","correct_answer":"It shows a person has turned to God and begins a new life as a follower of Jesus"}'::jsonb, 'The child has seen a baptism as an event and not heard what it stands for.', 'Offer "It is only a nice ceremony with water" beside "It shows a person has turned to God and begins a new life as a follower of Jesus" and ask the child to choose.', 'Link John 3:5 with Acts 2:38: repent and be baptised. Baptism marks a new life; ask what changes after.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS.M_C4_JR_MASTER', 'CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS', 'Thinks Joseph refused only because he feared his master.', '{"question":"Why did Joseph refuse, according to Genesis 39:9?","wrong_answer":"He was afraid of his master","correct_answer":"It would be a sin against God"}'::jsonb, 'The child gives a fear of people as the reason.', 'Offer "He was afraid of his master" beside "It would be a sin against God" and ask the child to choose.', 'Read Genesis 39:9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS.M_C4_JR_STAYED', 'CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS', 'Thinks Joseph stayed to argue.', '{"question":"What did Joseph do when she held on to his cloak?","wrong_answer":"He stayed to argue","correct_answer":"He left the cloak and ran out of the house"}'::jsonb, 'The child thinks bravery means staying.', 'Offer "He stayed to argue" beside "He left the cloak and ran out of the house" and ask the child to choose.', 'Read Genesis 39:12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS.M_C4_JR_PRIVATE', 'CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS', 'Thinks it is safe to do wrong when no one else is there.', '{"question":"Joseph was alone with her in the house. What was his reasoning?","wrong_answer":"No one is here, so no one will know","correct_answer":"God sees, so it is wrong even when no one else is there"}'::jsonb, 'Children learn that wrong is only wrong if seen.', 'Offer "No one is here, so no one will know" beside "God sees, so it is wrong even when no one else is there" and ask the child to choose.', 'Link to Genesis 39:9 and 39:11.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.SAFE_PEOPLE.M_C4_SP_KIND_STRANGER', 'CRES.G4.CHRIST.TRUST.SAFE_PEOPLE', 'Thinks a stranger who offers sweets or a lift is safe because he is kind.', '{"question":"A stranger offers you sweets and a lift home. What should you do?","wrong_answer":"Accept, because he is kind","correct_answer":"Say NO, go away and tell a trusted adult"}'::jsonb, 'The child confuses kindness with safety.', 'Offer "Accept, because he is kind" beside "Say NO, go away and tell a trusted adult" and ask the child to choose.', 'Role-play a firm NO and walking to a shop, a teacher or a parent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.SAFE_PEOPLE.M_C4_SP_ALL_ADULTS', 'CRES.G4.CHRIST.TRUST.SAFE_PEOPLE', 'Thinks every adult can be trusted to take a child anywhere.', '{"question":"Which of these is a trusted person for a child?","wrong_answer":"Any adult who tells me to come","correct_answer":"My parent, my teacher or a church leader I know"}'::jsonb, 'Children are taught to obey adults.', 'Offer "Any adult who tells me to come" beside "My parent, my teacher or a church leader I know" and ask the child to choose.', 'List trusted people by name, and the rule that a trusted person never asks for a secret.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.SAFE_PEOPLE.M_C4_SP_NO_TELL', 'CRES.G4.CHRIST.TRUST.SAFE_PEOPLE', 'Thinks a child should not report because nobody will believe or help.', '{"question":"Whom can you report to if you are in danger?","wrong_answer":"No one, they will not believe me","correct_answer":"A parent, a teacher, the chief or Childline Kenya on 116"}'::jsonb, 'Fear and shame stop a child from reporting.', 'Offer "No one, they will not believe me" beside "A parent, a teacher, the chief or Childline Kenya on 116" and ask the child to choose.', 'Say the list aloud and practise telling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.TRUST_GOD.M_C4_TG_NO_TROUBLE', 'CRES.G4.CHRIST.TRUST.TRUST_GOD', 'Thinks trusting God means no trouble will come.', '{"question":"What does it mean to trust in the Lord, according to Psalm 125:1?","wrong_answer":"Nothing bad will ever happen","correct_answer":"To stand firm like Mount Zion, even in trouble"}'::jsonb, 'The child hears trust as a promise of an easy life.', 'Offer "Nothing bad will ever happen" beside "To stand firm like Mount Zion, even in trouble" and ask the child to choose.', 'Read Psalm 125:1 and ask what Mount Zion does when the wind blows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.TRUST_GOD.M_C4_TG_LAZY', 'CRES.G4.CHRIST.TRUST.TRUST_GOD', 'Thinks that trusting God means doing nothing ourselves.', '{"question":"Wanjiru trusts God to help her in an exam. What fits?","wrong_answer":"She does not study, she just prays","correct_answer":"She studies and prays"}'::jsonb, 'Trust and work are set against each other.', 'Offer "She does not study, she just prays" beside "She studies and prays" and ask the child to choose.', 'Remind: the servants in the parable used what they had.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.TRUST_GOD.M_C4_TG_OWN_STRENGTH', 'CRES.G4.CHRIST.TRUST.TRUST_GOD', 'Thinks the strength of Mount Zion comes from us.', '{"question":"Why can those who trust in the Lord not be shaken?","wrong_answer":"Because they are strong in themselves","correct_answer":"Because God stands by them"}'::jsonb, 'The child thinks the verse praises human strength.', 'Offer "Because they are strong in themselves" beside "Because God stands by them" and ask the child to choose.', 'Read Psalm 125:1-2 and ask who surrounds the people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS.M_C4_JR_REWARDED_AT_ONCE', 'CRES.G4.CHRIST.TRUST.JOSEPH_RESISTS', 'Thinks Joseph was rewarded at once for doing right.', '{"question":"What happened to Joseph soon after he refused Potiphar''s wife?","wrong_answer":"He was made a ruler at once","correct_answer":"He was lied about and put in prison"}'::jsonb, 'The child expects good to be rewarded straight away.', 'Offer "He was made a ruler at once" beside "He was lied about and put in prison" and ask the child to choose.', 'Read Genesis 39:20 and then 41:41: doing right was costly first; God was with him in prison.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.SAFE_PEOPLE.M_C4_SP_PHONE_FRIEND', 'CRES.G4.CHRIST.TRUST.SAFE_PEOPLE', 'Thinks a person met on a phone or online is a trusted person because they know the child''s name.', '{"question":"Someone online knows your name and school and asks to meet. Is that a trusted person?","wrong_answer":"Yes, they know me","correct_answer":"No: tell a parent or teacher and do not meet"}'::jsonb, 'Knowing a name sounds like knowing the person.', 'Offer "Yes, they know me" beside "No: tell a parent or teacher and do not meet" and ask the child to choose.', 'Make two lists: people I know and trust at home, school and church; people who only know about me.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUST.TRUST_GOD.M_C4_TG_ZION_PLACE', 'CRES.G4.CHRIST.TRUST.TRUST_GOD', 'Thinks Psalm 125:1 is only about a mountain in Israel and not about people who trust God.', '{"question":"In Psalm 125:1, who is like Mount Zion?","wrong_answer":"Only the city of Jerusalem","correct_answer":"Those who trust in the Lord"}'::jsonb, 'The child keeps the place name and misses the comparison.', 'Offer "Only the city of Jerusalem" beside "Those who trust in the Lord" and ask the child to choose.', 'Read the verse in two halves: "Those who trust in the Lord / are like Mount Zion". Ask what the first half is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH.M_C4_TR_WHITE_LIE', 'CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH', 'Thinks a small lie to avoid trouble is fine.', '{"question":"You broke a cup by accident. What should you say?","wrong_answer":"It was not me","correct_answer":"It was me, and I am sorry"}'::jsonb, 'Small lies seem harmless.', 'Offer "It was not me" beside "It was me, and I am sorry" and ask the child to choose.', 'Role-play telling the truth and the parent''s kind answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH.M_C4_TR_LIE_LASTS', 'CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH', 'Reverses what Proverbs 12:19 says about lying lips.', '{"question":"What does Proverbs 12:19 say?","wrong_answer":"Lying lips last for ever","correct_answer":"Truthful lips endure for ever, a lying tongue only a moment"}'::jsonb, 'Verses are half remembered.', 'Offer "Lying lips last for ever" beside "Truthful lips endure for ever, a lying tongue only a moment" and ask the child to choose.', 'Write it on a flash card: truth lasts, lies do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH.M_C4_TR_HIDE', 'CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH', 'Thinks the truth should be hidden when it is embarrassing.', '{"question":"A child failed a test and is ashamed. What should he tell his father?","wrong_answer":"Say he did well","correct_answer":"Tell him the truth and ask for help"}'::jsonb, 'Shame makes a lie look easier.', 'Offer "Say he did well" beside "Tell him the truth and ask for help" and ask the child to choose.', 'Ask what the father can do once he knows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH.M_C4_TR_SILENCE', 'CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH', 'Thinks staying silent to let someone else be blamed is not lying.', '{"question":"Your friend is blamed for the broken window you broke, and you say nothing. Is that truthful?","wrong_answer":"Yes, I did not say anything false","correct_answer":"No: hiding the truth so someone else is blamed is deceit"}'::jsonb, 'The child thinks only spoken words can be lies.', 'Offer "Yes, I did not say anything false" beside "No: hiding the truth so someone else is blamed is deceit" and ask the child to choose.', 'Act it out: who is punished? Speaking truthfully to your neighbour (Ephesians 4:25) means owning up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE.M_C4_OB_IF_AGREE', 'CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE', 'Thinks we obey only when we agree.', '{"question":"When should a child obey his parents and teachers?","wrong_answer":"Only when I agree with them","correct_answer":"Always when it is right and safe"}'::jsonb, 'Obedience is treated as a choice every time.', 'Offer "Only when I agree with them" beside "Always when it is right and safe" and ask the child to choose.', 'Read Exodus 20:12 and Ephesians 6:1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE.M_C4_OB_NO_RESULT', 'CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE', 'Thinks disobedience has no result if not caught.', '{"question":"What may follow disobeying school rules?","wrong_answer":"Nothing, if the teacher is not looking","correct_answer":"Trouble, danger, and lost trust"}'::jsonb, 'Results seem to come only with punishment.', 'Offer "Nothing, if the teacher is not looking" beside "Trouble, danger, and lost trust" and ask the child to choose.', 'List the results: danger, lost trust, punishment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE.M_C4_OB_RULES_HOME', 'CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE', 'Thinks obedience applies at home but not to school rules.', '{"question":"Whose instructions should a child follow at school?","wrong_answer":"Only those from my parents","correct_answer":"The teachers and the school rules"}'::jsonb, 'The child separates home and school.', 'Offer "Only those from my parents" beside "The teachers and the school rules" and ask the child to choose.', 'Link school rules with safe, orderly learning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE.M_C4_OB_PROMISE', 'CRES.G4.CHRIST.OBEDIENCE_OBEDIENCE.OBEDIENCE', 'Gives the promise of Exodus 20:12 as riches or good marks, not a long life in the land.', '{"question":"What does Exodus 20:12 promise to those who honour their parents?","wrong_answer":"That they will be rich","correct_answer":"That they may live long in the land God gives"}'::jsonb, 'The child guesses a reward he would like.', 'Offer "That they will be rich" beside "That they may live long in the land God gives" and ask the child to choose.', 'Read the second half of Exodus 20:12 aloud twice and underline "live long".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN.M_C4_LC_DISCIPLES', 'CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN', 'Thinks the disciples welcomed the children.', '{"question":"What did the disciples do when people brought children to Jesus?","wrong_answer":"They welcomed the children","correct_answer":"They told the people off"}'::jsonb, 'The child expects the friends of Jesus to be kind.', 'Offer "They welcomed the children" beside "They told the people off" and ask the child to choose.', 'Read Matthew 19:13.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN.M_C4_LC_BUSY', 'CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN', 'Thinks Jesus sent the children away because he was busy.', '{"question":"What did Jesus say about the children?","wrong_answer":"Send them away, I am busy","correct_answer":"Let the little children come to me"}'::jsonb, 'Adults are often too busy for children.', 'Offer "Send them away, I am busy" beside "Let the little children come to me" and ask the child to choose.', 'Read Matthew 19:14.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN.M_C4_LC_NO_HANDS', 'CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN', 'Thinks Jesus did not bless or pray for the children.', '{"question":"What did Jesus do for the children?","wrong_answer":"Nothing, he only spoke to the adults","correct_answer":"He placed his hands on them and blessed them"}'::jsonb, 'The child focuses on the disciples.', 'Offer "Nothing, he only spoke to the adults" beside "He placed his hands on them and blessed them" and ask the child to choose.', 'Read Matthew 19:15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN.M_C4_LC_GROWN_UPS_FIRST', 'CRES.G4.CHRIST.LOVE_LOVE.LOVE_CHILDREN', 'Thinks the kingdom of heaven belongs to grown-ups and children must wait.', '{"question":"To whom does the kingdom of heaven belong, according to Matthew 19:14?","wrong_answer":"Only to grown-ups who have done a lot","correct_answer":"To such as these little children"}'::jsonb, 'In daily life adults go first, so the child expects the same in God''s kingdom.', 'Offer "Only to grown-ups who have done a lot" beside "To such as these little children" and ask the child to choose.', 'Read Matthew 19:14 and ask: who does Jesus point to? Children are welcomed now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS.M_C4_CI_NOBODY', 'CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS', 'Thinks school property belongs to nobody, so there is no need to care for it.', '{"question":"Whose are the desks and library books at school?","wrong_answer":"Nobody''s, so it does not matter","correct_answer":"The whole school''s, so we all care for them"}'::jsonb, 'Public things seem to have no owner.', 'Offer "Nobody''s, so it does not matter" beside "The whole school''s, so we all care for them" and ask the child to choose.', 'Ask who would use the desk tomorrow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS.M_C4_CI_REPLACE', 'CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS', 'Thinks it does not matter if an item is lost because parents will buy another.', '{"question":"Your textbook is torn because you were careless. What is the best response?","wrong_answer":"It does not matter, my parents can buy another","correct_answer":"Take better care and mend it"}'::jsonb, 'Children do not see the cost of things.', 'Offer "It does not matter, my parents can buy another" beside "Take better care and mend it" and ask the child to choose.', 'Ask what a parent gives up to buy a book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS.M_C4_CI_ONLY_PERSONAL', 'CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS', 'Thinks only one''s own items need care.', '{"question":"Which items should a child take care of?","wrong_answer":"Only my own things","correct_answer":"My own things and the school''s"}'::jsonb, 'The child cares only about his belongings.', 'Offer "Only my own things" beside "My own things and the school''s" and ask the child to choose.', 'List both kinds on the board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS.M_C4_CI_SOMEONE_ELSE', 'CRES.G4.CHRIST.RESPONSIBILITY_PERSONAL_.CARE_ITEMS', 'Thinks caring for school property is only the cleaner''s or the teacher''s job.', '{"question":"A tap in the school compound is left running. Whose job is it to close it?","wrong_answer":"Only the cleaner''s","correct_answer":"Anyone who sees it, including me"}'::jsonb, 'The child sees jobs as belonging to the adult paid for them.', 'Offer "Only the cleaner''s" beside "Anyone who sees it, including me" and ask the child to choose.', 'Walk the compound and list things any child can care for: taps, books, desks, flowers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.HOLINESS.HOLINESS.M_C4_HOL_MY_BODY', 'CRES.G4.CHRIST.HOLINESS.HOLINESS', 'Thinks my body is mine to do what I like with.', '{"question":"What does 1 Corinthians 6:19-20 say about your body?","wrong_answer":"It is mine, to do what I want","correct_answer":"It is a temple of the Holy Spirit, so honour God with it"}'::jsonb, 'The child hears "my body, my choice" in other places.', 'Offer "It is mine, to do what I want" beside "It is a temple of the Holy Spirit, so honour God with it" and ask the child to choose.', 'Read the verse and the words "you are not your own".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.HOLINESS.HOLINESS.M_C4_HOL_BUILDING', 'CRES.G4.CHRIST.HOLINESS.HOLINESS', 'Thinks that the temple in the verse is only the church building.', '{"question":"In 1 Corinthians 6:19, what is the temple?","wrong_answer":"The church building","correct_answer":"Your own body"}'::jsonb, 'The word temple is linked with a building.', 'Offer "The church building" beside "Your own body" and ask the child to choose.', 'Read the verse again: "your bodies are temples".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.HOLINESS.HOLINESS.M_C4_HOL_TEST', 'CRES.G4.CHRIST.HOLINESS.HOLINESS', 'Thinks it is fine to stay in tempting places if we do not sin.', '{"question":"Your friends go to a place where children smoke. What is wise?","wrong_answer":"Go along and just watch","correct_answer":"Keep away from that place"}'::jsonb, 'The child trusts his own strength.', 'Offer "Go along and just watch" beside "Keep away from that place" and ask the child to choose.', 'Link with Joseph, who ran.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.CHRIST.HOLINESS.HOLINESS.M_C4_HOL_FOOD_ONLY', 'CRES.G4.CHRIST.HOLINESS.HOLINESS', 'Thinks honouring God with the body means only eating good food.', '{"question":"Which of these honours God with your body?","wrong_answer":"Only eating well","correct_answer":"Keeping away from what harms it and using it to do good"}'::jsonb, 'Health lessons talk about food, so the child narrows the idea.', 'Offer "Only eating well" beside "Keeping away from what harms it and using it to do good" and ask the child to choose.', 'Make a body outline and write good uses beside each part: hands to help, mouth to speak kindly, feet to go to good places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD.M_C4_HG_DROVE_WORSHIPPERS', 'CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD', 'Thinks Jesus drove out the worshippers.', '{"question":"Whom did Jesus drive out of the temple?","wrong_answer":"The people praying","correct_answer":"Those buying and selling there"}'::jsonb, 'The child does not remember who was in the temple.', 'Offer "The people praying" beside "Those buying and selling there" and ask the child to choose.', 'Read Matthew 21:12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD.M_C4_HG_BUSINESS_OK', 'CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD', 'Thinks buying and selling in the house of God is fine.', '{"question":"What did Jesus say the temple should be?","wrong_answer":"A market for trading","correct_answer":"A house of prayer"}'::jsonb, 'Business is part of daily life.', 'Offer "A market for trading" beside "A house of prayer" and ask the child to choose.', 'Read Matthew 21:13.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD.M_C4_HG_SERVICE_ONLY', 'CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD', 'Thinks we need respect the church only during a service.', '{"question":"When should we respect the church?","wrong_answer":"Only during the service","correct_answer":"Always, because it is God''s house"}'::jsonb, 'Respect is seen as a rule for a service.', 'Offer "Only during the service" beside "Always, because it is God''s house" and ask the child to choose.', 'List ways of respecting the church every day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD.M_C4_HG_HEALED', 'CRES.G4.THE_CH.HOUSE_OF_GOD.HOUSE_OF_GOD', 'Forgets that Jesus healed the blind and the lame in the temple after clearing it.', '{"question":"Who came to Jesus at the temple after he drove out the traders (Matthew 21:14)?","wrong_answer":"Nobody, the temple was empty","correct_answer":"The blind and the lame, and he healed them"}'::jsonb, 'The driving out is dramatic and the healing is lost.', 'Offer "Nobody, the temple was empty" beside "The blind and the lame, and he healed them" and ask the child to choose.', 'Read Matthew 21:14. Jesus cleared the temple for prayer and for healing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES.M_C4_TD_PAUL', 'CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES', 'Counts Paul among the twelve.', '{"question":"Who was one of the twelve disciples?","wrong_answer":"Paul","correct_answer":"Philip"}'::jsonb, 'Paul is a famous apostle.', 'Offer "Paul" beside "Philip" and ask the child to choose.', 'Read the list in Matthew 10:2-4 and look for Paul.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES.M_C4_TD_BROTHERS', 'CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES', 'Mixes who the brothers were.', '{"question":"Whose brother was Andrew?","wrong_answer":"John''s","correct_answer":"Simon Peter''s"}'::jsonb, 'Pairs of names are close in the list.', 'Offer "John''s" beside "Simon Peter''s" and ask the child to choose.', 'Read Matthew 10:2: "Simon called Peter and his brother Andrew".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES.M_C4_TD_COUNT', 'CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES', 'Says Jesus chose seven disciples, mixing the twelve with the seven chosen to serve in Acts 6 or with the days of the week.', '{"question":"How many disciples did Jesus choose?","wrong_answer":"Seven","correct_answer":"Twelve"}'::jsonb, 'The child mixes with other Bible numbers.', 'Offer "Seven" beside "Twelve" and ask the child to choose.', 'Count the names in Matthew 10:2-4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS.M_C4_CB_WHO', 'CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS', 'Thinks Jesus himself preached on the day of Pentecost.', '{"question":"Who preached to the crowd in Acts 2?","wrong_answer":"Jesus","correct_answer":"Peter"}'::jsonb, 'Jesus is the main teacher in the Gospels.', 'Offer "Jesus" beside "Peter" and ask the child to choose.', 'Read Acts 2:14 and 2:38.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS.M_C4_CB_NUMBER', 'CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS', 'Says twelve people joined the church that day, mixing the twelve disciples with the three thousand who believed.', '{"question":"About how many people joined the believers that day?","wrong_answer":"Twelve","correct_answer":"Three thousand"}'::jsonb, 'Small numbers are more familiar to children.', 'Offer "Twelve" beside "Three thousand" and ask the child to choose.', 'Read Acts 2:41.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS.M_C4_CB_ONLY_BAPTISM', 'CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS', 'Thinks Acts 2:38 asks only for baptism with no change of life.', '{"question":"What did Peter tell the people to do first, in Acts 2:38?","wrong_answer":"Only to be baptised","correct_answer":"To repent, and be baptised"}'::jsonb, 'The child remembers the ceremony and forgets the turning.', 'Offer "Only to be baptised" beside "To repent, and be baptised" and ask the child to choose.', 'Read the verse and note the first word, repent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES.M_C4_TD_MATTHEW_FISHER', 'CRES.G4.THE_CH.THE_EARLY_CHURCH.TWELVE_DISCIPLES', 'Thinks every disciple was a fisherman.', '{"question":"What was Matthew''s work before he followed Jesus (Matthew 10:3)?","wrong_answer":"A fisherman","correct_answer":"A tax collector"}'::jsonb, 'The best-known call stories are of fishermen.', 'Offer "A fisherman" beside "A tax collector" and ask the child to choose.', 'Read Matthew 10:3 and 9:9. Make two groups: fishermen (Peter, Andrew, James, John) and Matthew the tax collector.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS.M_C4_CB_PLACE', 'CRES.G4.THE_CH.THE_EARLY_CHURCH.CHURCH_BEGINS', 'Places the start of the church in Rome or Antioch instead of Jerusalem.', '{"question":"In which city did the church begin on the day of Pentecost (Acts 2)?","wrong_answer":"Rome","correct_answer":"Jerusalem"}'::jsonb, 'The child knows other famous church cities from later lessons.', 'Offer "Rome" beside "Jerusalem" and ask the child to choose.', 'Read Acts 2:5 ("staying in Jerusalem") and mark Jerusalem on a map. Antioch comes later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN.M_C4_ST_REVENGE', 'CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN', 'Thinks Stephen asked God to punish those who stoned him.', '{"question":"What did Stephen pray for those stoning him?","wrong_answer":"That God would punish them","correct_answer":"That God would not hold this sin against them"}'::jsonb, 'Revenge is expected of a hurt person.', 'Offer "That God would punish them" beside "That God would not hold this sin against them" and ask the child to choose.', 'Read Acts 7:60.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN.M_C4_ST_CITY', 'CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN', 'Says believers were first called Christians in Jerusalem, where the church began, instead of Antioch (Acts 11:26).', '{"question":"In which city were believers first called Christians?","wrong_answer":"Jerusalem","correct_answer":"Antioch"}'::jsonb, 'Jerusalem is the city most known in Acts.', 'Offer "Jerusalem" beside "Antioch" and ask the child to choose.', 'Find Antioch on a Bible map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN.M_C4_ST_GROUP', 'CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN', 'Thinks it is fine to join a group that does not follow Jesus if friends do.', '{"question":"Your friends join a group that mocks Jesus. What should you do?","wrong_answer":"Join them to fit in","correct_answer":"Politely refuse and stand firm in your faith"}'::jsonb, 'The wish to belong.', 'Offer "Join them to fit in" beside "Politely refuse and stand firm in your faith" and ask the child to choose.', 'Role-play a polite no.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN.M_C4_ST_SAUL', 'CRES.G4.THE_CH.STANDING_FIRM_IN_FAITH.STEPHEN', 'Forgets that Saul was there, holding the coats, when Stephen was stoned.', '{"question":"Who looked after the coats of the men who stoned Stephen (Acts 7:58)?","wrong_answer":"Peter","correct_answer":"A young man named Saul"}'::jsonb, 'The child does not yet know Saul, who became Paul.', 'Offer "Peter" beside "A young man named Saul" and ask the child to choose.', 'Read Acts 7:58 and say: this Saul later became the apostle Paul.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER.M_C4_LP_BREAD', 'CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER', 'Thinks "daily bread" means asking for riches or only bread.', '{"question":"What do we ask for when we pray \"Give us today our daily bread\"?","wrong_answer":"Riches for ever","correct_answer":"What we need each day"}'::jsonb, 'The words are taken literally.', 'Offer "Riches for ever" beside "What we need each day" and ask the child to choose.', 'Ask what a child needs each day: food, clothes, health.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER.M_C4_LP_FORGIVE', 'CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER', 'Thinks we may ask for forgiveness without forgiving others.', '{"question":"What does the Lord''s Prayer say about forgiveness?","wrong_answer":"Forgive us, and we need not forgive others","correct_answer":"Forgive us as we forgive others"}'::jsonb, 'The second half is left out.', 'Offer "Forgive us, and we need not forgive others" beside "Forgive us as we forgive others" and ask the child to choose.', 'Read Matthew 6:12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER.M_C4_LP_ONLY_CHURCH', 'CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER', 'Thinks Christians pray only at church or once a week.', '{"question":"When should we pray?","wrong_answer":"Only at church","correct_answer":"Every day, at home and anywhere"}'::jsonb, 'Prayer is linked with services.', 'Offer "Only at church" beside "Every day, at home and anywhere" and ask the child to choose.', 'Make a list of times: morning, meals, bedtime.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER.M_C4_LP_KINGDOM', 'CRES.G4.THE_CH.THE_LORD_S_PRAYER.LORDS_PRAYER', 'Thinks "your kingdom come" asks for a country or a king to rule Kenya.', '{"question":"What do we ask for when we pray \"your kingdom come\"?","wrong_answer":"For a new king to rule Kenya","correct_answer":"That God''s rule and will be done on earth as in heaven"}'::jsonb, 'The child knows kingdom as a land with a king.', 'Offer "For a new king to rule Kenya" beside "That God''s rule and will be done on earth as in heaven" and ask the child to choose.', 'Read the next line too: "your will be done, on earth as it is in heaven". The kingdom is God''s rule in people''s lives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT.M_C4_FR_FOOD', 'CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'Thinks the fruit of the Spirit are real fruits like mango or banana.', '{"question":"What are the fruit of the Spirit in Galatians 5:22-23?","wrong_answer":"Mangoes and bananas","correct_answer":"Love, joy, peace, patience and others"}'::jsonb, 'The word fruit means food to a child.', 'Offer "Mangoes and bananas" beside "Love, joy, peace, patience and others" and ask the child to choose.', 'Say that fruit here means what grows in a person''s life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT.M_C4_FR_BAD', 'CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'Puts a work of the flesh, such as jealousy, in the list of the fruit of the Spirit.', '{"question":"Which of these is a fruit of the Spirit?","wrong_answer":"Jealousy","correct_answer":"Kindness"}'::jsonb, 'Sorting good from bad is quick but slips.', 'Offer "Jealousy" beside "Kindness" and ask the child to choose.', 'Sort cards into fruit and not fruit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT.M_C4_FR_CHURCH_ONLY', 'CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'Thinks the fruit of the Spirit show only in church.', '{"question":"Where should the fruit of the Spirit show?","wrong_answer":"Only in church","correct_answer":"Everywhere, at home, school and church"}'::jsonb, 'Faith is linked with services.', 'Offer "Only in church" beside "Everywhere, at home, school and church" and ask the child to choose.', 'Give examples at a football game.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT.M_C4_FR_COUNT', 'CRES.G4.THE_CH.FRUIT_OF_THE_HOLY_SPIRIT.FRUIT_SPIRIT', 'Thinks there are only five fruit of the Spirit, the number learnt in Grade 3.', '{"question":"How many fruit of the Spirit are named in Galatians 5:22-23?","wrong_answer":"Five","correct_answer":"Nine"}'::jsonb, 'Grade 3 asked for five, so the child thinks five is the whole list.', 'Offer "Five" beside "Nine" and ask the child to choose.', 'Count them on the fingers from the verse: love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, self-control.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL.M_C4_SC_FEELINGS', 'CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL', 'Thinks self-control means doing whatever one feels like.', '{"question":"What is self-control?","wrong_answer":"Doing whatever I feel like","correct_answer":"Choosing what is right instead of what my feeling pushes me to do"}'::jsonb, 'Control is confused with freedom.', 'Offer "Doing whatever I feel like" beside "Choosing what is right instead of what my feeling pushes me to do" and ask the child to choose.', 'Role-play counting to ten when angry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL.M_C4_SC_OWN_POWER', 'CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL', 'Thinks self-control comes only from our own strength.', '{"question":"Where does self-control come from, according to Galatians 5:22-25?","wrong_answer":"Only from my own strength","correct_answer":"It is a fruit of the Holy Spirit"}'::jsonb, 'The word control sounds like effort.', 'Offer "Only from my own strength" beside "It is a fruit of the Holy Spirit" and ask the child to choose.', 'Read Galatians 5:23 and 5:25.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL.M_C4_SC_SECRET_OK', 'CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL', 'Thinks drugs or harmful videos are fine if done in secret.', '{"question":"A friend offers you a harmful video to watch in secret. What shows self-control?","wrong_answer":"Watch it, since no one will know","correct_answer":"Refuse and keep your mind and body clean"}'::jsonb, 'Secrecy seems to remove the harm.', 'Offer "Watch it, since no one will know" beside "Refuse and keep your mind and body clean" and ask the child to choose.', 'Ask what harm comes even if nobody finds out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL.M_C4_SC_ONCE', 'CRES.G4.THE_CH.SELF_CONTROL.SELF_CONTROL', 'Thinks trying something harmful once does no harm.', '{"question":"A friend says \"just try one cigarette, once is nothing\". What does self-control say?","wrong_answer":"Once is fine","correct_answer":"No: say no every time"}'::jsonb, 'The child thinks harm comes only from doing something often.', 'Offer "Once is fine" beside "No: say no every time" and ask the child to choose.', 'Explain that habits start with once, and practise saying no politely but firmly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA.M_C4_SM_STRANGER', 'CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks an online stranger who is friendly can be trusted.', '{"question":"A stranger online asks to chat in private and meet. What should you do?","wrong_answer":"Chat and meet, he is friendly","correct_answer":"Not reply, and tell a parent or teacher"}'::jsonb, 'The child cannot tell who is really online.', 'Offer "Chat and meet, he is friendly" beside "Not reply, and tell a parent or teacher" and ask the child to choose.', 'Say that people can lie about who they are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA.M_C4_SM_PRIVATE', 'CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks it is safe to share passwords and the home address.', '{"question":"Which should you keep private online?","wrong_answer":"My favourite song","correct_answer":"My password and home address"}'::jsonb, 'Friends share things freely.', 'Offer "My favourite song" beside "My password and home address" and ask the child to choose.', 'List what a stranger could do with a password.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA.M_C4_SM_NOBODY', 'CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks it is fine to do wrong online if nobody will know.', '{"question":"You find a way to send an unkind joke about a classmate without your name. What shows integrity?","wrong_answer":"Send it, nobody will know","correct_answer":"Do not send it, because it would hurt"}'::jsonb, 'Anonymity feels like permission.', 'Offer "Send it, nobody will know" beside "Do not send it, because it would hurt" and ask the child to choose.', 'Ask whether God knows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA.M_C4_SM_DEVICE', 'CRES.G4.MORALI.USE_OF_SOCIAL_MEDIA.SOCIAL_MEDIA', 'Counts a non-digital object as a digital device.', '{"question":"Which of these is a digital device?","wrong_answer":"A pencil","correct_answer":"A mobile phone"}'::jsonb, 'Digital is confused with modern or useful.', 'Offer "A pencil" beside "A mobile phone" and ask the child to choose.', 'Show a phone, a tablet and a pencil and ask which needs power and a screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
